programs.sol:
"""Approximate a lexical 'like' response, not general semantic similarity.

The word and its -like/_like suffixes dominate the salient peaks. Appearance
phrases, polite requests and lists of examples weaken the lowercase response.
There is a small response on the next word in 'like a/this/that', on related
spellings (even fragments in unrelated words), and on Chinese comparison words.
Fate/destiny vocabulary has a secondary positive response. Other background
activations are left at zero. Only the previous token is remembered, per document.
"""
READS = ()

APPEARANCE = {
    'look', 'looks', 'looked', 'looking', 'sound', 'sounds', 'sounded',
    'taste', 'tastes', 'smell', 'smells',
}
FEELING = {'feel', 'feels', 'felt', 'seem', 'seems'}
EXAMPLE_NOUNS = {
    'tools', 'techniques', 'methods', 'factors', 'features', 'products',
    'platforms', 'resources', 'applications', 'algorithms', 'items', 'words',
    'things', 'accessories', 'foods', 'services', 'apps', 'topics', 'choices',
}
CHINESE_COMPARISONS = {'像', '像是', '就像', '就像是', '如同', '犹如', '仿佛'}
CHINESE_FATE = {'命运', '命運', '的命运', '的命運'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = 0.0
    if previous == 'like':
        if word in {'this', 'that'}:
            value = 0.07
        elif word in {'a', 'an'}:
            value = 0.04
        elif word in {'i', 'it'}:
            value = 0.03
    if word in {'like', '-like', '_like'}:
        if word != 'like' or raw.strip() != 'like':
            value = 0.58
        elif not raw.startswith(' '):
            value = 0.48
        elif previous in APPEARANCE:
            value = 0.16
        elif previous in FEELING or previous in {'would', "'d", '’d'}:
            value = 0.22
        elif previous in EXAMPLE_NOUNS:
            value = 0.14
        elif previous in {'the', 'and', 'but', "'s", '’s'}:
            value = 0.58
        elif previous in {'is', 'was', 'were', 'are', 'be', 'just',
                          'much', 'nothing', 'to', 'of', 'in', 'for', 'with'}:
            value = 0.51
        elif (previous.isalpha() and previous.endswith('s')
              and previous not in {'his', 'this', 'its', 'us', 'as',
                                   'thus', 'ours', 'yours', 'others'}):
            # A rough, readable cue for an unlisted plural example noun.
            value = 0.27
        else:
            value = 0.42
    elif word == 'alike':
        value = 0.51
    elif word == 'likes':
        value = 0.38
    elif word == 'liked':
        value = 0.23
    elif word == 'ike':
        value = 0.29
    elif word in {'ikes', 'lik'}:
        value = 0.12
    elif word in {'likely', 'unlikely'}:
        value = 0.04
    elif word == 'unlike':
        value = 0.16
    elif word in CHINESE_COMPARISONS:
        value = 0.28
    elif word in {'fate', 'destiny'}:
        value = 0.29
    elif word in CHINESE_FATE:
        value = 0.44
    return (doc, word), value

programs.luna:
"""Predict positive pulses for heads and leaders: office-holders get a
stronger value, other top/first/head words a smaller one, and an office's
following “of” gets an intermediate pulse.
"""
READS = ()

OFFICES = {
    "boss", "captain", "chair", "chairman", "chief", "commander",
    "ceo", "director", "governor", "head", "leader", "manager",
    "mayor", "minister", "officer", "president", "secretary", "senior",
    "deputy", "founder", "ambassador", "advisor", "owner", "ruler",
    "senator", "representative", "official", "supervisor", "lord",
    "king", "executive", "master", "principal", "premier", "首相",
    "领导", "老板", "负责人", "主播", "глав", "cabeza",
}

FOREMOST = {
    "headquarters", "header", "lead", "leading", "capital", "prime",
    "main", "top", "peak", "champion", "winner", "first", "premiere",
    "debut", "keynote", "victory", "首", "主", "副", "引领", "頂",
    "头", "頭", "baş",
}

STRONG = {"leader", "chief", "president", "leadership", "headquarters"}


def clean(token):
    return token.strip().lower().strip(".,!?;:'\"()[]{}<>-_/\\*#")


def has_word(word, words):
    return (
        word in words
        or (word.endswith("s") and word[:-1] in words)
        or (word.endswith("es") and word[:-2] in words)
    )


def step(carry, prefix, upstream):
    word = clean(prefix.token_strings[-1])
    if has_word(word, STRONG):
        return None, 2.0
    if has_word(word, OFFICES):
        return None, 1.0
    if has_word(word, FOREMOST):
        return None, 0.5
    if len(prefix.token_ids) > 1:
        same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
        prior = clean(prefix.token_strings[-2])
        if same_doc and has_word(prior, OFFICES) and word == "of":
            return None, 0.75
    return None, 0.0

programs.sol:
"""Approximate a predominantly lexical, negative response to 'offer'.

Offer and its inflections are strongest; selected promise, transaction,
availability and threat words, including translations, are weaker. Common
word fragments have small negative responses; physical/physically are positive.
A split offer ending and its next article or preposition can also respond.
State resets at document boundaries. Unrecognized tokens predict zero.

This captures word forms, not whether an offer is actually being made; it
leaves the component's many smaller, idiosyncratic responses unmodeled.
"""
READS = ()

OFFER_FORMS = {
    'offer': -5.02, 'offers': -5.5, 'offered': -4.15,
    'offering': -4.55, 'offerings': -4.1,
}
RELATED = {
    'deal': -1.28, 'deals': -1.3, 'dealt': -1.4, 'dealing': -0.85,
    'promise': -1.02, 'promises': -1.08,
    'promised': -1.3, 'promising': -0.89,
}
# Offer, promise, transaction and payment words or stems in other languages.
RELATED_TRANSLATIONS = {
    'offre': -1.95, 'ofrec': -3.45, 'ofrece': -2.7, 'ofere': -2.4,
    'bietet': -2.1, 'bieten': -2.0, 'angebot': -2.25,
    'предлаг': -1.3, 'предлагает': -1.9, 'предостав': -0.64,
    '优惠': -1.17, '優惠': -1.7, '提供': -0.3, '제공': -0.8,
    '承诺': -0.7, '交易': -0.68, '报价': -1.3, 'bied': -1.4,
    '払い': -0.9, '欠': -1.05, 'плат': -0.68,
}
WEAK_OFFER_RELATED = {
    'available', 'availability', 'feature', 'features', 'provides',
    'proposed', 'proposal', 'proposals', 'award', 'awarded', 'awards',
    'grant', 'grants', 'guaranteed', 'bid', 'bids', 'tender',
}
BENEFITS_AND_COMMITMENTS = {'opportunity', 'granted', 'granting', 'guarantee', 'afford'}
FOLLOWING = {
    'a': 0.16, 'an': 0.19, 'the': 0.20, 'of': 0.15, 'you': 0.14,
    'my': 0.065, 'your': 0.065, 'their': 0.065,
    'this': 0.065, 'some': 0.065, 'to': 0.03, 'by': 0.05, 'for': 0.04,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    offer_strength = 0.0
    if word in OFFER_FORMS:
        value = OFFER_FORMS[word]
        if token.strip() == 'Offering':
            value += 0.75
        elif token.strip() == 'Offer':
            value -= 0.25
        elif token.strip() == 'Offers':
            value += 0.65
        if token == 'offer':
            value += 0.6
        elif token == 'offers':
            value += 1.3
        offer_strength = -value
    elif word in RELATED:
        value = RELATED[word]
        if token.strip() == 'Promise':
            value = -0.35
        elif token == 'deal':
            value = -0.45
    elif word in RELATED_TRANSLATIONS:
        value = RELATED_TRANSLATIONS[word]
    elif word in {'threat', 'threats', 'threaten', 'threatens',
                  'threatened', 'threatening'}:
        value = -0.65
    elif word in {'pose', 'poses'} and token.startswith(' '):
        value = -0.85
    elif word in {'refuse', 'refused', 'refusing', 'refuses', 'refusal'}:
        value = -0.6
    elif word in WEAK_OFFER_RELATED:
        value = -0.23
    elif word in {'provide', 'providing', 'supply', 'supplies', 'propose'}:
        value = -0.15 if token.startswith(' ') else 0.0
    elif word in BENEFITS_AND_COMMITMENTS:
        value = -0.38
    elif word in {'physical', 'physically'}:
        value = 0.62 if word == 'physical' else 0.5
    elif word == 'off':
        value = (-0.7 if token == ' OFF'
                 else -0.38 if token == 'off' else -0.16)
    elif token in {'er', 'ers', 'ering', 'ered', 'ffer'}:
        value = {'er': -0.1, 'ers': -0.12, 'ering': -0.5,
                 'ered': -0.55, 'ffer': -1.24}[token]
    if strength:
        if token in {'ed', 'ing', 'ings', 's'}:
            value = {'ed': -4.2, 'ing': -4.6, 'ings': -2.9, 's': -4.8}[token]
            offer_strength = -value
        elif token.startswith(' ') and word in FOLLOWING:
            value -= strength * FOLLOWING[word]
    elif (previous.strip().lower() == 'off'
          and token in {'er', 'ers', 'ered', 'ering'}):
        value = OFFER_FORMS.get('off' + token, -4.5)
        offer_strength = -value
    return (doc, token, offer_strength), float(value)

programs.luna:
"""Predict a few high-response Chinese word cues with fixed values."""

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    """Mark preparation, choice, intention, quantity, and action-related cues."""
    word = prefix.token_strings[-1].strip()

    if any(stem in word for stem in ("准备", "準備")):
        return None, 0.82
    if any(stem in word for stem in ("选择", "選擇")):
        return None, 0.65
    if "打算" in word:
        return None, 1.14
    if "不少" in word:
        return None, 0.80
    if word in {"尝试", "忍不住"}:
        return None, 0.65
    if word == "商品":
        return None, 0.58
    return None, 0.0

programs.sol:
"""A negative WALK/TALK/-ALK spelling detector with weaker semantic neighbors.

English roots and their inflections dominate the response; capitalization,
word-fragment tokenization and code punctuation change its strength. The last
token allows split spellings and endings to be recognized, plus the immediate
collocations 'talk about/to/of' and 'walk of/the'. Smaller lexical responses
cover walking, speaking, blogs/wikis and Chinese walking/speaking words.
Everything else is zero: this omits diffuse, weak token-specific responses.
"""

READS = ()
WALK_ENDINGS = {'': -5.75, 'ing': -5.35, 'ed': -4.65,
                's': -4.35, 'er': -3.7, 'ers': -4.1, 'through': -3.1}
TALK_ENDINGS = {'': -5.0, 'ing': -3.75, 'ed': -3.95,
                's': -3.9, 'er': -3.6, 'ers': -3.6}
SPEECH_VERBS = {'speak': -1.0, 'speaking': -0.9, 'speaks': -0.6,
                'spoke': -0.75, 'spoken': -0.28}


def word_part(token):
    return token.strip().lower().lstrip('._/(-')


def lexical_value(token):
    word = word_part(token)
    for stem, endings in [('walk', WALK_ENDINGS), ('talk', TALK_ENDINGS)]:
        if word.startswith(stem) and word[len(stem):] in endings:
            ending = word[len(stem):]
            value = endings[ending]
            if not ending:
                if token.startswith('_'):
                    return -4.2
                if token.startswith('.'):
                    return -5.6
                if token.startswith('-'):
                    return -4.0
                if stem == 'walk':
                    if token == 'walk':
                        return -7.0
                    return -6.2 if 'W' in token else value
                if token == 'Talk':
                    return -5.7
            if stem == 'walk' and ending == 'er' and 'W' in token:
                value = -4.0
            if token == 'walking':
                value = -6.7
            return value
    if word == 'alk':
        if token[:1].isspace():
            return -1.6
        return -4.8 if token.isupper() else -5.5
    if word in {'alking', 'alker', 'alked', 'alks', 'alkers'}:
        return -3.5 if word in {'alking', 'alker'} else -4.3
    if word in {'stalk', 'stalking', 'balk', 'chalk'}:
        if word == 'stalk':
            return -3.75 if token[:1].isspace() else -4.4
        if word == 'chalk' and token.startswith('('):
            return -1.4
        return -2.8
    if len(word) <= 5 and word.endswith('alk'):
        return -1.6
    if word in {'folk', 'olk'}:
        return -1.3 if word == 'folk' else -0.75
    if word == 'calc':
        return -1.05 if token[:1].isspace() else -0.6
    if word in SPEECH_VERBS:
        return SPEECH_VERBS[word]
    if word in {'discussion', 'discussions', 'discussing', 'chat'}:
        return -0.55
    if word in {'discuss', 'dialogue', 'speech', 'communicate', 'ask'}:
        return -0.33
    if word in {'parler', 'hablar', 'konuş'}:
        return -1.1
    if word in {'stroll', 'strolling'}:
        return -2.2
    if word in {'trot', 'trotting'}:
        return -1.25
    if word in {'crawl', 'crawling', 'crawler', 'wander', 'wandered',
                'wandering', 'travers', 'traverse', 'traversal', 'averse',
                'aversal'}:
        return -0.8
    if word in {'travel', 'travels', 'traveling', 'travelled', 'traveled',
                'journey', 'pedestrian', 'sidewalk', 'sidewalks'}:
        return -0.4
    if word in {'blog', 'blogs', 'blogging', 'blogger', 'bloggers'}:
        if word.startswith('blogg'):
            return -0.5
        return -1.05 if token[:1].isspace() else -0.7
    if word in {'wiki', 'wikipedia'}:
        if word == 'wiki':
            return -1.3 if token.startswith('/') else -2.1
        return -0.8 if token.startswith('.') else -0.5
    if word in {'步行', '行走', '漫步', '走路'}:
        return -2.6
    if word in {'散步', '徒步', '走', '走了', '走过', '走過', '走出', '走到'}:
        return -1.45
    if word in {'走进', '走近', '走访'}:
        return -1.9
    if word in {'讲', '講', '讲话', '讲师'}:
        return -1.0
    if word in {'话', '話', '谈', '談'}:
        return -0.55
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous, root = ('', '') if carry is None or carry[0] != doc else carry[1:]
    word = word_part(token)
    value = lexical_value(token)
    # Completing W+ALK or T+ALK is stronger than an arbitrary ALK fragment.
    if word in {'alk', 'alking', 'alker'} and not token[:1].isspace():
        before = word_part(previous)
        if before.endswith('w'):
            value = {'alk': -6.8, 'alking': -6.5, 'alker': -5.2}[word]
            if word == 'alk' and before == 'w':
                value = -7.2 if previous[:1].isspace() else -8.7
                if previous.lower() == 'w':
                    value = -7.2
            if token.isupper():
                value = -7.4
            word = 'w' + word
        elif before.endswith('t') and word != 'alker':
            value -= 1.0
            word = 't' + word
    # Inflections split off as separate tokens.
    if root in {'walk', 'talk', 'stalk', 'alk'}:
        if token in {'s', 'ed', 'ing', 'er', 'ers'}:
            value = -4.3 if root == 'walk' else -3.6
        elif token == 'ER':
            value = -1.65
    # Immediate collocations, not a persistent walking/talking topic state.
    if root in {'walk', 'talk'} and word == 'of':
        value = -1.9
    if root in {'talk', 'talking', 'talks', 'talked'}:
        if word == 'about':
            value = -0.5 if root == 'talk' else -0.33
        elif word == 'to':
            value = -0.65
    if root in {'walk', 'walking', 'walked', 'walks'} and word == 'the':
        value = -0.36
    return (doc, token, word), float(value)

programs.luna:
"""Use a strong cue for alk spellings and weaker communication-word cues."""

READS = ()

SOFT_COMMUNICATION = {
    "speak", "speaks", "speaking", "spoke", "spoken", "discuss",
    "discussion", "discussions", "chat", "chats", "blog", "blogs",
    "wiki",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    root = word.rstrip(".,!?;:'\"”’)")
    if root.startswith(("talk", "walk")):
        return None, -5.0
    if "alk" in root:
        return None, -1.5
    if root in SOFT_COMMUNICATION:
        return None, -0.9
    return None, 0.0

programs.sol:
"""A local grammar for generic reference: 'what kind', 'different parts',
'some time', 'this way'. Noun selectors excite generic noun heads, especially
questions. Plural heads receive a small extra response. Recognize selected
Chinese/Japanese equivalents, 'for example', and question continuations.
Keep a weaker two-token modifier trace, join split words, and reset at document
boundaries. Elsewhere predict zero, or a small negative value for modifiers.
"""
import string
READS = ()

# Generic heads, from strong taxonomic/partitive to weaker descriptive nouns.
HEADS = {}
for words, gain in (
    ('kind part aspect time age', 1.1),
    ('type sort form class category variety area field stage section sector '
     'extent year direction country', .9),
    ('way thing point place side level size day word language information '
     'number condition order purpose position component material function '
     'method property term location version', .65),
):
    for w in words.split():
        HEADS[w] = gain

MODIFIERS = {}
for words, gain in (
    ('what', 3.3), ('which whichever', 1.5), ('whatever', 1.2),
    ('certain different various following', 1.5),
    ('specific particular other another any some', .9),
    ('this that these those same similar such every each no', .6),
    ('important main major relevant related correct multiple several many few', .5),
    ('one two three both next new previous last', .2),
):
    for w in words.split():
        MODIFIERS[w] = gain
ASIAN_HEADS = set(('类 類 样 樣 样子 类型 種類 方面 领域 領域 部分 阶段 地区 '
    '时间 時間 年 時 时候 程度 地方 位置 方式 意思 内容 內容 东西 東西 '
    '条件 方法 语言 方向 年代 こと もの ため ところ').split())
FUNCTION = set(('a an the of to in on at by for from with and or but as than '
    'it its he she they we you i them their our your his her is was be').split())


def selector(word):
    if word.isascii():
        return MODIFIERS.get(word, 0.)
    if '任何' not in word and any(w in word for w in
            ('什么', '什麼', '什麽', '何', '哪', '啥', 'どんな', 'どの')):
        return 2.
    if any(w in word for w in ('各', '不同', '某', '特定', '以下', '诸', '諸')):
        return 1.3
    if word == '等':
        return 1.
    if any(w in word for w in ('这', '這', '那', '此', '该', '每', '其他',
                               '其它', '一些', '任何', '多个', '有些', '重要',
                               '相关', 'この', 'その', 'という', 'ような')):
        return .65
    return 0.


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    word = raw.strip().strip(string.punctuation).lower()
    if carry is None or carry[0] != doc:
        previous, prev, older, last = '', '', 0., 0.
    else:
        previous, prev, older, last = carry[1:]
    strength = selector(prev)
    fragment = (raw[:1].isascii() and raw[:1].isalpha()
                and previous[-1:].isascii() and previous[-1:].isalpha())
    if word.endswith('ies'):
        singular = word[:-3] + 'y'
    elif word.endswith('es') and word[:-2] in HEADS:
        singular = word[:-2]
    else:
        singular = word[:-1] if word.endswith('s') else word
    gain = HEADS.get(word, HEADS.get(singular))
    value = 0.
    if word in {'example', 'instance'} and prev == 'for':
        value = .8 if word == 'example' else .65
    elif word == 'of' and prev in {'kind', 'sort', 'type'}:
        value = .45 * last
    elif prev == 'what' and word in {'are', 'were', 'do', 'about'}:
        value = 1.5
    elif prev == 'what' and word in {'to', 'a', 'of', 'with', 'or', 'if'}:
        value = .9
    elif prev in {'which', 'whichever'} and word in {'are', 'were', 'in'}:
        value = .5
    elif gain is not None and not fragment:
        value = .04 + gain * (strength + .15 * older)
        if word.endswith('s'):
            value += .10
        if word == 'kind':
            value -= .15
    elif word.rstrip('的') in ASIAN_HEADS:
        value = .04 + 1.2 * (strength + .15 * older)
    elif word in MODIFIERS:
        value = -.05
    elif word in FUNCTION:
        value = -.05 if strength else 0.
    elif prev == 'what' and word.isalpha():
        value = .5
    elif not word.isascii():
        value = .35 * strength
    newest = prev + word if fragment else word
    return (doc, raw, newest[-80:], strength, value), float(value)

programs.haiku:
"""Layer 0, MLP down-projection, component 3015.

What it responds to: the head word of a noun phrase that asks about, or names, a
*kind of thing*, when that noun is introduced by a wh-word or a determiner/quantifier.
The strongest cases are "what KIND of", "what TYPE of", "what SORT of", "what FORM of"
(activations around 2-4); next come generic category nouns right after a
wh-word or determiner ("what PART", "various PARTS", "this TIME", "different KINDS",
"这个 领域", "各 方面"). The component is switched off in most text, so almost all of its
variance comes from these spikes; in ordinary words it sits near zero.

Rules, in plain terms (all read only the current token and the one or two before it):
  1. "what/which" + kind-noun (kind, type, sort, form, 种类, 类型, 样)      -> 2.8
  2. "what/which" + generic noun (part, time, way, field, 领域, 地方 ...)  -> 1.1
  3. "what/which" + "are/do/to/about/if" (question auxiliaries)         -> 0.2
  3b. "what/which" + a pronoun (I, we, they, he ...)                       -> -0.03
  4. determiner/quantifier + generic noun (this time, other ways, 该领域)  -> 0.5
  5. "kind/type/sort" + "of", after "what" or a determiner                 -> 0.4
  6. determiner + a pronoun/auxiliary/function word (not a noun)          -> -0.06
  7. any generic noun elsewhere                                            -> 0.03
Everything else predicts 0. The weights were fitted to the component's own activations on training text.
"""

READS = ()

WH = {"what", "which", "whatever", "whichever", "什么", "哪", "何"}
KIND = {"kind", "kinds", "type", "types", "sort", "sorts", "form", "forms", "种类", "类型", "样", "种", "类"}
DET = {
    "this", "that", "these", "those", "other", "same", "different", "each", "every", "some",
    "any", "all", "various", "certain", "particular", "specific", "several", "such", "another",
    "many", "no", "multiple", "following", "one", "two", "new", "main",
