PRONOUNS = {"i", "you", "we", "they", "he", "she", "it", "me", "them", "us", "him"}
FUNCTION = {"is", "are", "was", "were", "be", "and", "or", "but", "the", "a", "an", "to", "in", "of"}


def _word(s):
    return s.strip().lower()


def _is_generic(s):
    w = _word(s)
    return w in GENERIC or any(z in s for z in GENERIC if not z.isascii())


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = _word(tokens[-1])
    t = prefix.position
    # a document boundary resets the context: only use tokens from the same document
    same = lambda k: t - k >= 0 and prefix.document_ids[t - k] == prefix.document_ids[t]
    prev = _word(tokens[-2]) if same(1) else None
    prev2 = _word(tokens[-3]) if same(2) else None
    raw_cur = tokens[-1]

    value = 0.0
    if prev in WH:
        if cur in KIND:
            value = 2.8
        elif _is_generic(raw_cur):
            value = 1.1
        elif cur in AUX_AFTER_WH:
            value = 0.2
        elif cur in PRONOUNS:
            value = -0.03
    elif prev in DET:
        if _is_generic(raw_cur):
            value = 0.5
        elif cur in PRONOUNS or cur in FUNCTION:
            value = -0.06
    elif cur == "of" and prev in KIND and (prev2 in WH or prev2 in DET):
        value = 0.4
    elif _is_generic(raw_cur):
        value = 0.03
    return carry, float(value)

programs.sol:
"""A causative/change-of-state signal, especially the '-ize' meaning of 化.

English -ize/-ify endings, property-changing words, and conversion operations
have weaker positive responses. Separately tokenized endings are stronger.
Only the unfinished English word is retained, to interpret an ending; this
state resets between documents. Unrecognized text gives zero.
"""
import re

READS = ()

ENDINGS = {
    'ize': 1.3, 'ized': 1.6, 'izing': 1.0, 'izes': 0.9,
    'ization': 2.1, 'izations': 1.8, 'izer': 0.4, 'izers': 0.4,
    'ify': 1.85, 'ified': 1.5, 'ifying': 1.6, 'ifies': 1.5,
    'ification': 1.85, 'ifications': 1.1, 'ific': 0.75,
    'ifier': 0.65, 'ifiers': 0.5,
    'ise': 0.35, 'ised': 0.55, 'ising': 0.25, 'ises': 0.25,
    'isation': 1.3, 'isations': 1.0,
}
CAUSE = re.compile(r'(?:iz(?:e|es|ed|ing|ations?)|'
                   r'if(?:y|ies|ied|ying|ications?))$')
PROPERTY_BASES = (
    'modern', 'roman', 'social', 'standard', 'annual', 'spatial', 'natural',
    'regular', 'individual', 'personal', 'internal', 'global', 'national',
    'human', 'commercial', 'parallel', 'virtual', 'urban',
)
NOT_STATE_CHANGES = (
    'recogn', 'realiz', 'realis', 'utiliz', 'utilis', 'memor', 'emphas',
    'summar', 'authoriz', 'authoris', 'organiz', 'organis',
)
CONVERSION_STEMS = (
    'optim', 'normal', 'serial', 'deserial', 'personali', 'diversif',
    'purif', 'unif', 'general', 'special', 'random', 'stabil',
    'custom', 'local', 'standard', 'parametr',
)


def english(piece, word):
    separate = piece in ENDINGS and bool(CAUSE.fullmatch(piece))
    british = piece in ('ise', 'ised', 'ising', 'ises', 'isation', 'isations')
    nominal = piece.endswith(('ation', 'ations'))
    if piece in ('size', 'sizes', 'sized', 'prize', 'prizes', 'usize'):
        return 0.07  # these are not causative endings
    british_word = piece.startswith(CONVERSION_STEMS) and piece.endswith(
        ('ise', 'ises', 'ised', 'ising', 'isation', 'isations')
    )
    if separate or british or british_word or CAUSE.search(piece):
        if word.startswith(NOT_STATE_CHANGES):
            return 0.2 if not separate or nominal else -0.6
        if word.startswith('identif'):
            return 0.3 if separate else 0.15
        if word.startswith(('classif', 'specif', 'qualif', 'verif',
                            'exemplif', 'notif', 'testif')):
            return 1.0 if separate else 0.4
        if word.startswith(('simplif', 'implif')):
            return 3.1 if separate else 2.6
        if word.startswith(PROPERTY_BASES):
            if separate:
                return 3.1 if nominal else 2.3
            return 1.7
        if separate and word.startswith(('solidif', 'acidif', 'calcif',
                                         'quantif', 'electrif', 'diversif')):
            return 2.4
        if separate and word.startswith(('modif', 'clarif', 'purif')):
            return 1.15
        if word.startswith(CONVERSION_STEMS):
            return 1.8 if separate else 1.5
        return ENDINGS.get(piece, 0.8)
    # Other common processing and property-change words.
    if piece.startswith(('valid', 'invalid', 'modif', 'activat', 'initializ')):
        return 0.85
    if piece.startswith(('pars', 'decod', 'encod', 'refin', 'strengthen',
                         'differentiat', 'integrat', 'evolv', 'evolution')):
        return 0.65
    if piece.startswith(('chemical', 'biochemical')):
        return 1.0
    if piece.startswith('oxidation'):
        return 2.1
    if piece.startswith(('oxid', 'ferment', 'hydrat', 'phosphory')):
        return 0.65
    if re.fullmatch(r'automat(?:e|ed|ing|ion|ions)', piece):
        return 2.2
    if piece in ('serde', 'sizeof', 'stringify'):
        return 0.8
    return ENDINGS.get(piece, 1.0 if piece == 'simpl' else 0.0)


def chinese(s):
    if s in ('化', '化的'):
        return 6.7 if s == '化' else 5.6
    if '文化' in s:
        return 0.8  # culture: 化 is not being used as a productive suffix
    if any(w in s for w in ('变化', '變化', '消化', '催化')):
        return 1.2  # change, digestion, catalysis
    if s in ('转化', '恶化', '初始化'):
        return 1.8  # conversion, deterioration, initialization
    if s == '现代化':
        return 5.3  # modernization
    if s in ('绿化', '可视化', '化学'):
        return 2.2  # greening, visualization, chemistry
    if s in ('优化', '强化', '个性化', '数字化', '最大化', '化解'):
        return 3.1  # optimization and related adjustments
    return 3.9 if s.endswith('化') else 1.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    parts = re.findall(r'[A-Za-z]+', token)
    word = parts[-1].lower() if parts else ''
    if token.isascii() and token.isalpha():
        word = previous + token.lower()
    tail = word[-60:] if token and token[-1].isascii() and token[-1].isalpha() else ''
    s = token.strip()
    piece = s.lower().strip('._-/()')
    if '化' in s:
        value = chinese(s)
    elif s in ('화', 'hóa'):
        value = 3.6 if s == '화' else 4.4  # cognate causative endings
    elif re.fullmatch(r'изаци[яи]|ифика|ализ|'
                      r'iza(?:ci[oó]n|ção)|izzazione|'
                      r'if(?:icación|icação|icar)', s):
        value = 1.1  # corresponding Romance and Russian derivational endings
    else:
        value = english(piece, word if piece in ENDINGS else piece)
    return (doc, tail), float(value)

