AFFIXES = (
    ("ization", 2.34, 0.69),
    ("isation", 1.10, 0.28),
    ("ification", 1.48, 0.52),
    ("ifying", 1.69, 0.41),
    ("ified", 1.48, 0.46),
    ("izing", 0.93, 0.39),
    ("ized", 1.58, 0.63),
    ("alize", 1.18, 1.18),
    ("ify", 1.71, 0.41),
    ("ize", 1.13, 0.41),
)


