    word = prefix.token_strings[-1].strip()
    lower = word.lower()

    if word == "化":
        return None, 6.4
    if "化" in word:
        return None, 2.5 if word.endswith("化") else 3.2
    if word.endswith("화"):
        return None, 3.5

    if "valid" in lower:
        return None, 0.85
    if "parse" in lower:
        return None, 0.45
    if "modif" in lower:
        return None, 0.78
    if "chem" in lower:
        return None, 0.33
    if "oxid" in lower:
        return None, 0.65

    for ending, piece_value, word_value in AFFIXES:
        if lower == ending:
            return None, piece_value
        if lower.endswith(ending):
            if ending == "ize" and lower in {"size", "prize", "seize", "maize"}:
                return None, 0.0
            return None, word_value

    if lower.endswith("ation"):
        return None, 0.05

    return None, 0.0

"""Use spelling, word boundaries, and common English function words as cues."""
READS = ()

FUNCTION_WORDS = {
    "a", "an", "the", "and", "or", "but", "if", "to", "of", "in",
    "on", "at", "by", "for", "from", "with", "as", "is", "are",
    "was", "were", "be", "been", "it", "this", "that", "these",
    "those", "he", "she", "they", "we", "you", "i", "me", "my",
    "your", "our", "their", "his", "her", "them", "us", "who",
    "which", "what", "not", "do", "does", "did", "have", "has",
    "had", "can", "could", "will", "would", "should", "may", "might",
    "must", "just", "than", "so", "because", "while", "about", "into",
    "over", "after", "before", "up", "down", "out", "off", "during",
}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word in FUNCTION_WORDS:
        return None, -0.02

    spelling = token.lstrip()
    first = spelling[:1]
    letters = sum(char.isalpha() for char in spelling)
    value = 0.0

    if first.isalpha():
        value += 0.03
    if first.isupper():
        value += 0.05
    if token.startswith(" "):
        value += 0.03
    if any(ord(char) > 127 for char in spelling):
        value += 0.11
    if letters >= 4:
        value += 0.08
    if any(char.islower() for char in spelling):
        value -= 0.05
    if first.isdigit():
        value += 0.01

    return None, float(value)

