NUMBER_WORDS = {'four', 'fourth', 'five', 'fifth', 'fifty', 'fifteen'}
ORDER_WORDS = {'first', 'firstly', 'final', 'finally'}
QUANTITY_WORDS = {'few', 'fewer', 'fewest', 'full', 'fully'}
FIND_WORDS = {'find', 'finds', 'finding', 'found'}
FORM_WORDS = {
    'form', 'forms', 'formed', 'forming', 'formal', 'formation',
    'format', 'formatted', 'formatting', 'formula', 'formulas',
    'frame', 'frames', 'framework', 'frameworks',
}
FOLLOW_WORDS = {'follow', 'follows', 'following', 'followed'}
F_SUFFIXES = {'ft', 'fty', 'fter', 'ference', 'ferences', 'ferred', 'ful'}

# Fire, fly, flower, face, friend, family, fish, food, function, file,
# fault, football, finance, future, film, fund, female, free, forest,
# fix, fibre, flow, and facilities.
F_TRANSLATIONS = {
    '火', '飞', '飛', '花', '脸', '臉', '朋友', '友', '家族',
    '鱼', '魚', '食品', '食物', '食', '函数', '函', '功能',
    '文件', '故障', '足球', '金融', '未来', '未來', '电影',
    '電影', '基金', '女性', '自由', '森林', '修复', '修復',
    '纤维', '纖維', '流量', '免费', '免費', '设施', '設施',
}
# Some common Mandarin characters with an f-initial pronunciation.
PINYIN_F = frozenset(
    '发發法罚罰伐乏阀閥凡烦煩帆繁反返饭飯犯范範贩販'
    '方房防放访訪坊妨芳仿非飞飛肥费費废廢匪肺'
    '分份纷紛粉奋奮芬愤憤风風封丰豐峰蜂锋鋒凤鳳奉缝縫'
    '夫扶服福富父付府副幅负負符复復複伏浮弗妇婦辅輔附腐'
)


