            return -1.18 - 0.37 * bare.startswith('F')
        for words, value in (
            (NUMBER_WORDS, -0.61), (ORDER_WORDS, -0.84),
            (QUANTITY_WORDS, -1.17), (FIND_WORDS, -1.07),
            (FORM_WORDS, -1.00), (FOLLOW_WORDS, -0.87),
        ):
            if lower in words:
                return value
