        if lower in {'false', 'für', 'fois', 'frac', 'fraction'}:
            return -1.15
        if lower == 'fmt':
            return -1.61
        value = -1.64
        value -= 0.43 * bare.startswith('F')
        value -= 0.19 * (len(bare) > 1 and bare.isupper())
        value -= 0.51 * (len(bare) in (2, 3))
        value += 0.024 * min(max(len(bare) - 4, 0), 6)
