            value += 0.32 + 0.33 * (len(bare) == 1)
        value += 1.17 * lower.startswith('ff')
        value += 1.04 * (lower in F_SUFFIXES)
        return value
    value = -0.01
    first = bare[:1]
    if first.lower() == 'ф':
        value -= 0.71 + 0.71 * (len(bare) > 1)
    if first == 'ف' or bare.startswith('الف'):
        value -= 1.35
    if first.lower() in {'φ', 'ƒ'}:
        value -= 0.62
