READS = ()

# The core symbol spellings, including leading-space and fullwidth variants.
PULSES = {
    '?': 0.93,
    ' ?': 1.02,
    '!': 0.67,
    ' !': 0.53,
    '？': 0.60,
    '！': 0.40,
    '؟': 0.74,
    '@': 0.91,
    ' @': 0.78,
    '__': 1.49,
    ' __': 1.17,
}


def symbol_value(token):
    if token.strip().casefold() == 'mat':
        return -0.60 if token.startswith(' ') else -0.30
    if token in PULSES:
        return PULSES[token]
