        return 0.40 if s in ('(!', '.!') else 0.70

    if s[0] in '?!':
        ending = s[1:]
        if ending == '\\':
            return 0.43
        if ending == '\n':
            return 0.14
        if ending == '\n\n':
            return 0.10
        if ending in ('(', '(\"', '\"', '”', ')', '[', ','):
            return 0.18
    return 0.0


def step(carry, prefix, upstream):
    return None, symbol_value(prefix.token_strings[-1])

