        if token.startswith(' '):
            return -0.02 if syllable == 'a' else -0.045
        return -0.28 if token != syllable else (-0.13 if syllable == 'a' else -0.05)
    if len(syllable) == 1 and unicodedata.normalize('NFD', syllable)[0] in 'αΑ':
        return -0.85
    if syllable in ('á', 'Á') and start:
        return -0.65
    if syllable in ('ál', 'ā'):
        return -0.45
    if syllable in ('а', 'А'):
        if token.startswith(' '):
            return -0.95 if syllable == 'а' else -0.68
        return (-0.4 if syllable == 'а' else -1.1) if start else -0.1
    if low.startswith('аль'):
        return -0.3
    if low in ('ал', 'ар'):
        return -2.1 if start else -0.3
    return A_SYLLABLES.get(syllable, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, previous)
    if '\ufffd' in token:
        # A split UTF-8 token can complete a Greek alpha character.
        last = prefix.text_prefixes[-1][-1:]
        if last and unicodedata.normalize('NFD', last)[0] in 'αΑ':
            value = -1.3 if last == 'Α' else -0.9
    return (doc, (previous + token)[-40:]), float(value)

"""A context-sensitive comma/list-separator signal.

Bare ASCII and fullwidth commas get a recent-comma bonus and a bonus for
longer preceding token pieces. Recent symbol density weakens the response;
progress into a line strengthens it. There is also a document-start
transient. Arabic and punctuation-joined commas get fixed values, and other
tokens get zero. State resets at each document boundary. Coefficients were
fitted on training activations; no token-identity lookup table is used.
"""
from math import exp

READS = ()
COMMAS = ',，،'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 10000, 0, '', '')
    _, position, gap, line_age, previous, tail = carry

    if token in (',', '，'):
        symbols = sum(not (c.isalnum() or c.isspace()) for c in tail)
        # A short gap indicates successive list/clause separators.
        repetition = exp(-gap / 4)
        symbol_density = min(symbols / 60, 0.35)
        line_progress = min(line_age, 32) / 32
        previous_length = min(len(previous.strip()), 12)
        early_document = exp(-position / 4)
        if token == ',':
            value = (0.300 + 2.036 * repetition - 3.465 * symbol_density
                     + 0.422 * line_progress + 0.039 * previous_length
                     + 0.607 * early_document)
            if position == 0:
                value = 1.25
        else:
            value = (0.098 + 1.780 * repetition - 1.229 * symbol_density
                     + 0.458 * line_progress + 0.049 * previous_length
                     + 0.382 * early_document)
        value = min(2.7, max(-0.4, value))
    elif token == '،':
        value = 0.59
    elif any(c in token for c in COMMAS) and '\n' not in token:
        if token == '),':
            value = 0.35
        elif token.startswith(' '):
            value = 0.13
        elif token.startswith(','):
            value = 0.30 if '"' in token else 0.0
        elif '%' in token:
            value = 0.90
        elif '$' in token or '`' in token or '”' in token or '’' in token:
            value = 0.60
        elif '.' in token:
            value = 0.22
        elif ']' in token:
            value = 0.14
        else:
            value = 0.10
    else:
        value = 0.0

    gap = 1 if any(c in token for c in COMMAS) else gap + 1
    line_age = 1 if '\n' in token else line_age + 1
    carry = (doc, position + 1, gap, line_age,
             token, (tail + token)[-60:])
    return carry, float(value)

"""Approximate a letter-boundary cue, using only neighboring token text.

A one-letter segment at a token's end may start a word or be a stand-alone
label. Joined consonant/vowel fragments get negative estimates; many following
delimiters, operators, and connecting words get positive estimates. Amplitudes
depend on letter classes, case, accents, and the preceding token's boundary.
The amplitudes are coarse training estimates, not a token-ID lookup. Unrelated
lexical variation is omitted. Letter-labeled cells and two chat/tool boundaries
have explicit positive estimates. State is just the previous token and document.
"""
import re
import unicodedata as ud

READS: tuple[str, ...] = ()
VOWELS = set('aeiouаеёиоуыэюяіїєαεηιουω')
NASALS_AND_VOICELESS_STOPS = set('mnckptмнкпт')
CONNECTORS = set('is are be and or of to in with for by as on such '
                 'approaches equals times mod per'.split())
SIGNS = {
    '=': 0.63,
    '^': 0.29,
    '_': 0.64,
    '(': 0.44,
    ')': 0.28,
    ',': 0.58,
    ':': 0.58,
    '.': 0.04,
    "'": 0.15,
}


def base(c):
    return ud.normalize('NFD', c).lower()[0]


def last_letter(s):
    match = re.search(r'[^\W\d_]+$', s)
    if not match or len(match[0]) != 1 or s.startswith(("'", '’', '\\')):
        return None
    letter = match[0]
    name = ud.name(letter, '')
    scripts = ('LATIN', 'CYRILLIC', 'GREEK', 'MATHEMATICAL')
    if not any(script in name for script in scripts):
        return None
    stem = s[:-1]
    # Word-initial, bare, inside an opening delimiter, or otherwise attached.
    if stem and stem.isspace():
        style = 0
    elif not stem:
        style = 1
    else:
        style = 2 if stem[-1] in '([{' else 3
    return letter, name, style


def continuation(letter, name, style, s):
    b, first = base(letter), base(s[0])
    if b in VOWELS or 'GREEK' in name:
        return -0.03 if first in VOWELS and s[0].islower() else 0.0
    if b in NASALS_AND_VOICELESS_STOPS:
        gain = 1.0
    elif b in 'jжчцшщ':           # Affricate/hushing consonants.
        gain = 0.35
    elif b in 'wxyй':             # Semivowels and coordinate-variable letters.
        gain = 0.5
    else:
        gain = 0.72
    value = (-0.51, -0.23, -0.33, -0.16)[style] * gain
    if letter.isupper():
        value *= 0.9
    if 'CYRILLIC' in name and style == 1:
        value *= 0.55
    if 'LATIN' in name and not letter.isascii():
        value *= 0.08
    if s[0].isupper():
        value *= 0.65 if s.isupper() and first in VOWELS else -0.15
    elif first in VOWELS:
        value *= 1.3 if len(ud.normalize('NFD', s[0])) > 1 else 1.0
    else:
        value *= 0.6 if first in 'rlhwyрлйь' else 0.1
    return value


def boundary(letter, style, s):
    w = s.strip()
    if not w:
        if len(s) == 1 and s not in '\n\r\t':
            value = 0.57
        else:
            value = 0.24 if '\n' in s else 0.4
        return value * (1.0, 0.5, 0.7, 0.5)[style]
    first = w[0]
    if s[0].isspace() and first.isalpha():
        if w in {'cell', 'cells'} and letter in 'BT':
            return 0.8
        if len(w) == 1:
            return 0.03
        if w.lower() in CONNECTORS:
            if letter == 'I':
                return 0.11
            if base(letter) in VOWELS:
                return (0.55 if letter == 'a' else 0.26) if style == 0 else 0.15
            return 0.42 * (1.0, 0.5, 1.0, 0.3)[style]
        return 0.01 if base(letter) in VOWELS else 0.14 * (1.0, 0.5, 1.0, 0.3)[style]
    if first.isdecimal():
        digit = int(first)
        values = (0.21, 0.14, 0.04) if style in (0, 2) else (0.04, -0.02, -0.10)
        return values[0 if digit < 2 else 1 if digit == 2 else 2]
    if w.startswith(('.sub', '.sup')):
        first = '_'
    if first == '-' and w[1:2].isalpha():
        value = 0.70
    elif first in '+-*/':
        value = 0.52 * (1.2 if style == 2 else 1.0)
    elif first == '\\':
        value = 0.03 if w[1:2].isalpha() else 0.12 if style == 1 else 0.44
    elif len(w) > 1 and first in ',;:)]}':
        value = 0.12
    elif first in '_$<>&|#':
        value = SIGNS.get(first, 0.35)
    else:
        value = SIGNS.get(first, 0.13)
    value *= (1.0, 0.67, 1.0, 0.7)[style]
    if base(letter) in VOWELS or letter.lower() in 'xy':
        if first not in '=_':
            value *= 0.75
    return value


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    old = carry[1] if carry and carry[0] == doc else ''
    carry = (doc, s)
    if old in {'</tool_call>', '</tool_response>'}:
        return carry, 0.44
    if s == '<tool_call>':
        return carry, 0.25
    info = last_letter(old)
    if info is None:
        return carry, 0.015 if s and s[0].islower() and base(s[0]) in VOWELS else 0.0
    letter, name, style = info
    if s and s[0].isalpha():
        return carry, float(continuation(letter, name, style, s))
    value = boundary(letter, style, s)
    if 'CYRILLIC' in name:
        value *= 0.5
    return carry, float(value)

programs.haiku:
"""layers.0.mlp.down_proj:3025 -- an operator-after-variable detector.

What it does: this component writes into the residual stream mainly through the
MLP hidden unit 3025 of layer 0. It is near zero almost everywhere. It is clearly
positive on an operator or punctuation mark that directly follows a one-letter
Latin variable name, as in algebra or code: "a =", "n +", "x (", "b _", "c ,".
"=" and "+" are the strongest. Mid-word fragments that follow a single letter
are pushed negative, and so are fragments after a one-letter Cyrillic token.
Other things that give a smaller positive value are the end-of-turn token
<|im_end|> and a bare "=" that is not after a variable.

The rule needs only the previous and current token, so it is a lookup over
concepts (variable, operator, word fragment), not a table of token ids.
"""

READS = ()

OPERATOR_STRONG = ("=", "==", "+", "(", "_", "-", ":")


def _is_variable(s):
    # a one-letter Latin name, optionally led by a space or an opening bracket
    s = s.lstrip(" (")
    return len(s) == 1 and s.isascii() and s.isalpha()


def _is_cyrillic_letter(s):
    s = s.lstrip(" (")
    return len(s) == 1 and "Ѐ" <= s <= "ӿ"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if cur == "<|im_end|>":
        return carry, 0.24
    if _is_cyrillic_letter(prev) and cur[:1] != " " and cur.isalpha():
        return carry, -0.2
    if not _is_variable(prev):
        return carry, 0.05 if cur.strip() in ("=", "==") else 0.0
    # the token after a one-letter variable
    if cur.strip() == "":
        value = 0.2
    elif cur[0] != " " and cur.isalpha():
        value = -0.18  # continuation of a word
    elif cur.strip().isalnum() or cur.strip() in (".", "\n", "\t"):
        value = 0.0  # digits, plain words, full stops and line breaks
    elif cur.strip() in OPERATOR_STRONG:
        value = 0.57
    else:
        value = 0.25  # other punctuation and operators
    return carry, float(value)

programs.sol:
"""A lexical Boolean detector, not an evaluator of whether statements are true.

True/false tokens get large positive predictions. Capitalization, attached
punctuation, and the preceding nonblank token adjust their strength. Smaller
rules cover null values, Boolean types/predicates, control-flow words, empty
containers, selected belief words, and black/blue. Everything else gets zero.
The remembered token resets at each document boundary. These coarse rules
omit many weak, token-specific responses observed in training.
"""
import re

READS = ()
_VALUE = re.compile(r'^[\s=(:,\[\{./_>]*(true|false|True|False|TRUE|FALSE)$')
_WORD = re.compile(r'^[\s=(:,\[\{./_-]*([A-Za-z]+)$')
_NULLS = {'null': 1.1, 'NULL': 1.4, 'None': 1.25, 'nil': 1.5,
          'nullptr': 1.7, 'undefined': 0.75}
_TYPES = {'bool', 'boolean', 'Boolean', 'Bool'}
_PROSE = {'is', 'are', 'be', 'a', 'the', 'was', 'always', 'not'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    new_carry = (doc, token.rstrip() if token.strip() else previous)
    match = _VALUE.fullmatch(token)
    if match:
        word = match.group(1)
        truth = word.lower() == 'true'
        value = 6.3 if truth else 5.5
        if word == 'True':
            value = 6.6
        leader = token[:-len(word)].strip()
        if leader.endswith(('_', '.', '/')):
            return new_carry, 4.6 if truth else 4.4
        if leader.endswith('>'):
            return new_carry, 6.0 if truth else 4.7
        if word.isupper():
            value -= 0.6 if truth else 0.8
        elif previous.strip() == 'while' and truth:
            value = 5.2
        elif token.lstrip().startswith('='):
            value = 6.5 if truth else 5.1
        elif previous.endswith('='):
            value += 0.4 if truth else 0.1
        elif ':' in token or previous.endswith(':'):
            value += 0.35
        elif '(' in token:
            value += 0.4 if truth else 0.7
        elif previous.strip() == 'return':
            value = 6.1 if truth and word.islower() else value
            if not truth:
                value = 5.3
        elif word.islower() and previous.strip() in _PROSE:
            value -= 0.9 if truth else 0.65
        return new_carry, value
    match = _WORD.fullmatch(token)
    if match:
        word = match.group(1)
        lower = word.lower()
        if word in _NULLS:
            value = _NULLS[word] + (0.4 if '(' in token or '=' in token else 0.0)
        elif word in _TYPES:
            value = 0.75
        elif lower in {'else', 'elsif'}:
            value = 0.6
        elif lower == 'continue':
            value = 0.2
        elif lower in {'return', 'break'}:
            value = 0.4
        elif lower in {'belief', 'beliefs', 'believed'}:
            value = 1.0
        elif lower in {'believe', 'believes', 'truly'}:
            value = 0.75
        elif lower in {'asserttrue', 'assertfalse', 'istrue', 'isfalse',
                       'tobetruthy', 'tobefalsy'}:
            value = 1.9
        elif lower in {'falsely', 'untrue'}:
            value = 3.2
        elif lower == 'alse' and previous.strip().lower() == 'f':
            value = 2.2
        elif lower in {'black', 'blue'}:
            value = 1.05 if word[0].isupper() else 0.8
        else:
            value = 0.0
        return new_carry, value
    if re.fullmatch(r'[\s=(]*(?:\[\]|\{\})[,;\s]*', token):
        return new_carry, 0.65
    return new_carry, 0.0

programs.haiku:
"""Truth-value and null-value literal detector.

The component reads only the current token (it sits in layer 0, so its input is
mostly the token's own embedding). It fires strongly on the boolean literals
true and false, in any capitalisation and with a leading code punctuation mark
(" true", "=True", "(false"); moderately on null-like literals (null, nil, None,
NULL, undefined) and on words about truth and belief (bool, boolean, believe,
belief, truly, falsely, assertTrue); and weakly on a few code keywords
(return, else, break) and on the colours black and blue.
"""

READS = ()

TRUTH_LITERALS = {"true": 6.3, "false": 5.4}
NULL_LITERALS = {"null": 1.1, "nil": 1.5, "none": 1.3, "undefined": 0.7}
TRUTH_WORDS = {"bool": 0.7, "boolean": 0.8, "believe": 0.8, "belief": 1.0,
               "truly": 0.7, "falsely": 3.2, "asserttrue": 1.6, "assertfalse": 2.2}
WEAK_WORDS = {"black": 0.9, "blue": 0.9, "else": 0.6, "return": 0.45, "break": 0.4}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(" \t\n=(:_,.[]{}\"'").lower()
    for table in (TRUTH_LITERALS, NULL_LITERALS, TRUTH_WORDS, WEAK_WORDS):
        if word in table:
            return None, table[word]
    return None, 0.0

programs.luna:
"""Approximate a sparse truth-and-control vocabulary feature.

The component is usually quiet, but responds strongly to literal truth values
in code.  This rule gives those literals a large pulse and weaker pulses to
related null values, boolean language, and control-flow terms.
"""
import re

READS = ()

# These are the ordinary spellings of boolean and missing-value literals.
TRUTH_VALUES = {"true", "false"}
EMPTY_VALUES = {"none", "null", "nil"}
BOOLEAN_WORDS = {"bool", "boolean", "belief", "believe", "truly"}
CONTROL_WORDS = {"else", "return", "continue"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    words = re.findall(r"[^\W\d_]+", token, flags=re.UNICODE)
    if not words:
        return None, 0.0
    word = words[-1]
    if word in TRUTH_VALUES:
        return None, 6.2
    if word in EMPTY_VALUES:
        return None, 1.2
    if word in BOOLEAN_WORDS:
        return None, 0.8
    if word in CONTROL_WORDS:
        return None, 0.5
    return None, 0.0

programs.sol:
"""A lexical approximation: pronouns, month names, conversational spellings.

The main positive cases are English 'its', 'your' and 'you'. Capitalization,
spacing, and the immediately preceding word alter their predicted strength.
Month names are a separate positive class. Other recognized cases include
selected non-English second-person forms, pleasantries, and spellings that
can be contractions without apostrophes. Bare 'its' continuing a word and
unspaced 'im' receive smaller values. This is not a general syntax parser:
it predicts zero on all unlisted tokens, omitting diffuse small responses.
"""

READS = ()
MONTHS = frozenset('January February March April May June July August '
                   'September October November December'.split())
MONTH_ABBREVIATIONS = frozenset('Jan Feb Mar Apr Jun Jul Aug Sep Sept Oct '
                                'Nov Dec'.split())
PREPOSITIONS = frozenset('of in to for on with by from at into through about '
                         'over under during without'.split())
CLAUSE_LINKS = frozenset('and or but that as when while where because since '
                         'although than which what how so then'.split())
OBJECT_VERBS = frozenset('give tell show help ask thank'.split())

CONTRACTIONS = frozenset('im dont cant wont doesnt didnt isnt wasnt arent '
                         'thats hes shes lets youre whats'.split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower()
    spaced = token != token.lstrip()
    capital = text[:1].isupper()
    same_doc = (len(prefix.document_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2] if same_doc else ''
    prev_word = previous.strip().lower()
    punctuation = bool(previous) and previous[-1:] in ',;:!?()'
    boundary = spaced or not previous or not previous[-1:].isalpha()

    value = 0.0
    if word == 'you':
        if capital or not spaced:
            value = 0.96
        elif prev_word in {'thank', 'give'}:
            value = 0.27
        elif prev_word in OBJECT_VERBS:
            value = 0.53
        elif prev_word in {'if', 'do', 'can', 'could', 'would', 'will'}:
            value = 0.64
        elif prev_word in CLAUSE_LINKS:
            value = 0.90
        elif prev_word in PREPOSITIONS:
            value = 0.72
        elif punctuation:
            value = 0.86
        else:
            value = 0.76
    elif word == 'your':
        if not spaced or capital:
            value = 1.5 if not spaced else 1.43
        elif prev_word in PREPOSITIONS:
            value = 1.12
        elif prev_word in CLAUSE_LINKS or prev_word == 'if':
            value = 1.48
        elif punctuation:
            value = 1.5
        else:
            value = 1.22
    elif word == 'yours':
        value = 1.0
    elif word == 'its':
        if text == 'Its':
            value = 2.42 if spaced else 3.0
        elif text.isupper():
            value = 1.4 if spaced else 0.6
        elif spaced:
            if prev_word in PREPOSITIONS:
                value = 1.35
            elif prev_word in CLAUSE_LINKS or punctuation:
                value = 2.10
            else:
                value = 1.60
        else:
            value = 2.45 if boundary else 0.25
    elif word == 'itself':
        value = 0.42
    elif word in {'yourself', 'yourselves', 'thy', 'thine', 'thou'}:
        value = 0.25
    elif text in MONTHS:
        value = 0.65 if spaced else 0.50
    elif text in MONTH_ABBREVIATIONS:
        value = 0.22
    elif word == 'may':
        value = 0.06
    elif word in CONTRACTIONS:
        if word == 'im':
            value = 1.6 if text == 'Im' else (0.92 if spaced else 0.30)
        elif boundary:
            if word in {'youre', 'whats'}:
                value = 2.6
            elif word == 'thats':
                value = 1.8
            else:
                value = 0.95
    elif text == 'i':
        value = 0.22 if spaced else 0.06
    elif word == 'am':
        value = 0.24 if spaced else 0.0
    elif word in {'thanks', 'hey'}:
        value = 0.60 if word == 'thanks' else 0.45
    elif word == 'well':
        value = 0.42 if capital else 0.12
    elif text in {'你', '你的', '你们', '你們'}:
        value = 0.85
    elif text in {'您', '您的'}:
        value = 0.4
    elif word in {'votre', 'vous', 'você', 'bạn', 'あなた'}:
        value = 0.48
    elif word in {'ваш', 'ваша', 'ваше', 'ваши'}:
        value = 0.85
    return None, value

programs.luna:
"""Approximate rare positive pulses on capitalized months and pronouns.

Strong observed responses cluster on month names, second-person words, and a
few possessives. Capitalization helps distinguish a month from ordinary uses
such as the modal verb “may”; unrecognized tokens are predicted as zero.
"""

READS = ()

MONTHS = frozenset({
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
})

SECOND_PERSON = frozenset({
    "you", "your", "yours", "yourself", "yourselves",
    "you're", "youre", "you've", "youve", "you'll", "youll",
    "you'd", "youd", "你", "你的", "你们", "您",
})
POSSESSIVES = frozenset({"its"})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold()
    if token[:1].isupper() and word in MONTHS:
        return None, 0.7
    if word in SECOND_PERSON:
        return None, 1.03
    if word in POSSESSIVES:
        return None, 1.5
    return None, 0.0

programs.haiku:
"""Layer-0 MLP down-projection feature 3029: "inner Slavic word-ending pieces".

What it does, in plain terms
- It is a weak, mostly negative detector for the *ending* of a word that the
  tokenizer has split into several pieces. It fires negative on a non-initial piece
  (no leading space, and the previous piece is also letters) that is a typical
  Russian/Slavic adjective or noun ending: -но, -ный, -ной, -ного, -ное, -ская, -ский,
  -ство, -ность, -ник, -ск, ...
- Weaker negative values for the same kind of mid-word piece in Latin-script
  Slavic/Romance endings (-ny, -na, -ne, -ka, -mente), and for mid-word pieces written
  in Hangul, Arabic or Cyrillic in general.
- Everything else (whole words, word-initial pieces, punctuation, code) predicts 0.

Scale: values are roughly the mean activation on each class, in the component's units.
Word-internal position is judged from the text prefix only (causal).
"""

import unicodedata

READS = ()

# Russian/Slavic adjective and noun endings, as word-internal pieces.
SLAVIC_ENDINGS = {
    "но", "ного", "ный", "ной", "ное", "ная", "ную", "ные", "ным", "ными", "ном",
    "ств", "ство", "ства", "ский", "ская", "ской", "ское", "ск", "ник", "ность", "ности",
}
# The same kind of ending spelled in Latin letters (Polish, Czech, Romance, ...).
LATIN_ENDINGS = {"na", "ne", "ny", "ka", "no", "ja", "ki", "mente"}


def _is_letters(text):
    return text != "" and all(unicodedata.category(c).startswith("L") for c in text)


def _script(text):
    for c in text:
        if c.isalpha():
            return unicodedata.name(c, "").split(" ")[0]
    return ""


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else " "
    if len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        previous = " "
    # Word-internal: a letter piece that continues a letter piece with no space between.
    inner = _is_letters(token) and _is_letters(previous)
    if inner and token in SLAVIC_ENDINGS:
        return carry, -0.4
    if inner and token in LATIN_ENDINGS:
        return carry, -0.2
    if inner and _script(token) == "HANGUL":
        return carry, -0.04
    if inner and _script(token) == "ARABIC":
        return carry, -0.03
    if inner and _script(token) == "CYRILLIC":
        return carry, -0.012
    return carry, 0.0

