programs.haiku:
"""Polarity-word detector for layer-0 MLP component 3031 (down_proj).

This component is a 'positive / negative' word detector. It fires strongly on the word
"positive" (any form: positively, Positive, positivity) and on "negative" (any form), and
on their translations: yang 阳/陽 (the positive pole of yin-yang), yin 阴/陰, and 积极,
肯定 (affirmative, positive) and 消极 (negative). It fires more weakly on the plus sign
"+" (about 0.6; " +" with a space about 0.3) and the word "plus", and weakly on "even",
"yes", and "male"/"female". Every other token predicts 0, which is nearly its typical value.

Why: the strongest contributions are the polarity words; the other words are the same
binary-contrast family (plus/minus, even/odd, yes, male/female), and are weak.
"""
READS = ()

# Typical activation for each word, measured on training text.
STRENGTH = {
    "positive": 5.7, "negative": 3.8,           # English polarity words (any form)
    "陽": 7.0, "阳": 7.0, "阴": 4.5, "陰": 4.5,  # yang (positive pole), yin (negative pole)
    "积极": 2.6, "肯定": 2.3, "消极": 3.2,      # Chinese: active/affirmative, passive/negative
    "+": 0.6, "plus": 0.6, "even": 0.75, "yes": 1.3,
    "female": 0.9, "male": 0.9,
}


def word(s):
    """The token's text, lowercased, without spaces or dashes around it."""
    return s.strip().strip("-").lower()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]   # the newest token, decoded alone
    w = word(s)
    if w.startswith("positiv"):
        v = STRENGTH["positive"]
    elif w.startswith("negativ"):
        v = STRENGTH["negative"]
    elif s == " +":
        v = 0.3
    elif w in STRENGTH:
        v = STRENGTH[w]
    else:
        v = 0.0
    return None, float(v)

programs.luna:
"""A sparse lexical approximation using polarity words and arithmetic markers."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word == "positive":
        return None, 6.0
    if token.strip().startswith(("+", "±")):
        return None, 0.5
    if word == "plus":
        return None, 0.7
    if word == "negative":
        return None, 3.7
    if word in ("neg", "negation"):
        return None, 1.2
    if word == "even":
        return None, 0.7
    return None, 0.0

programs.sol:
"""A local collocation approximation to a public/common-use response.

Predict negative values on completions of public declarations and civic terms,
common mathematical phrases, user-facing software terms and application MIME
types. Standalone carriage returns and context-dependent ``void`` types are
positive.
Selected Chinese equivalents and Korean 'user' are included. Only the previous
token is kept; document boundaries reset it. Most weaker, idiosyncratic token
responses and longer-context effects are deliberately omitted.
"""
READS = ()


def words(text):
    return frozenset(text.split())


PUBLIC_CODE = (
    (-2.15, words('function boolean final')),
    (-1.65, words('static')),
    (-1.4, words('override abstract const struct')),
    (-1.0, words('class int String bool interface')),
    (-0.65, words('float double List string')),
)
PUBLIC_TOPICS = (
    (-2.7, words('health speaking writing transport key facing')),
    (-1.5, words('''
        service services works opinion policy speech holidays holiday sphere
        domain life affairs servants servant figures relations interest safety
        goods land sector license law schools school library utilities art
        spaces order letter document ist it ity
    ''')),
)
COMMON_PHRASES = (
    (-1.7, words('ratio factor factors divisor multiple multiples difference '
                 'ancestor law')),
    (-2.0, words('wealth core stock mode')),
    (-1.0, words('denominator knowledge sense ground good name names market '
                 'cause causes interests')),
)
USER_PHRASES = (
    (-1.8, words('agent guide')),
    (-0.6, words('''
        interface experience experiences behavior behaviour id name profile
        manual account data password input cache model type agreement
        authentication
    ''')),
    (-1.2, words('warning')),
)
SERVICE_PHRASES = (
    (-1.2, words('service services support protection spending')),
    (-0.8, words('based')),
)
OTHER_PHRASES = {
    'client': ((-1.0, words('secret')),),
    'shared': ((-1.25, words('by decision')),
               (-0.6, words('with experience experiences'))),
    'application': ((-2.0, words('specific')), (-1.3, words('layer')),
                    (-1.8, words('field type')),
                    (-0.7, words('form forms process server'))),
    'usage': ((-0.3, words('for')), (-0.43, words('by')),
              (-0.14, words('in as'))),
    'openness': ((-0.8, words('ai minded metrics belief among')),
                 (-0.5, words('api')), (-1.6, words('culture'))),
}
FUNCTION_WORDS = words('''
    a an the and or but is are was were be been to of in on at by for from with
    as that this it its have has can will not into than so
''')
# Equivalent public/use/user concepts; short forms also cover split words.
ROOTS = {
    '公': 'public', '公共': 'public', '公众': 'public',
    '用户': 'user', '客户': 'customer', '共同': 'common',
    '应用': 'application', '的应用': 'application', '用': 'use', '使用': 'use',
}
TERMS = {
    '函': 'letter', '法': 'law', '文': 'document',
    '衛': 'health', '卫生': 'health', '健康': 'health', '人物': 'figures',
    '帐号': 'account', '账号': 'account', '界面': 'interface', '手册': 'manual',
    '输入': 'input', '支持': 'support', '领域': 'field', '型': 'type',
    '意': 'purpose', '作': 'as', '以': 'for',
    '说明': 'instructions', '心得': 'experience',
}


def word(token):
    return token.strip().lstrip("._/-('").lower()


def response(word, groups, fallback=0.0):
    for value, vocabulary in groups:
        if word in vocabulary:
            return value
    return fallback


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    p, w = word(previous), word(token)
    p, w = ROOTS.get(p, p), TERMS.get(w, w)
    value = 0.0
    if token == '\r':
        value = 1.0
    elif w == 'void' or token == '<void':
        value = 1.1 if first else {
            'public': -0.27 if previous.startswith('\t') else -0.5,
            'private': 2.4, 'protected': 1.7, 'static': 1.15,
            'virtual': 0.8, 'abstract': 0.16,
        }.get(p, 0.55)
    elif p == 'public':
        fallback = -0.25 if w.isalpha() and w not in FUNCTION_WORDS else 0.0
        value = response(token.strip(), PUBLIC_CODE, None)
        if value is None:
            value = response(w, PUBLIC_TOPICS, fallback)
        if previous.startswith('\t'):
            value *= 0.8
        elif previous.strip() == 'Public' and w == 'health':
            value = -2.3
    elif p == 'common':
        fallback = -0.3 if w.isalpha() and w not in FUNCTION_WORDS else 0.0
        value = response(w, COMMON_PHRASES, fallback)
    elif p == 'user':
        value = response(w, USER_PHRASES)
        if token.startswith('-') and w in words('friendly defined space facing doc'):
            value = -1.5
    elif p in {'customer', 'consumer', 'community'}:
        value = response(w, SERVICE_PHRASES)
    elif p in {'client', 'shared', 'application'}:
        value = response(w, OTHER_PHRASES[p])
        if p == 'application':
            if token.startswith('/') and w in words('json xml x vnd pdf octet'):
                value = -2.9
            elif token.startswith('_') and w in {'json', 'xml'}:
                value = -2.0
    elif p in {'private', 'protected'} and w == 'static':
        value = 0.65
    elif p in {'use', 'used', 'available', 'applied'}:
        value = response(w, OTHER_PHRASES['usage'])
        if p == 'used' and w == 'to':
            value = 0.13
        elif p == 'use':
            value = response(w, (
                (-0.85, words('strict theme package')),
                (-1.3, words('purpose law')),
                (-0.9, words('instructions experience')),
            ), value)
    elif p == 'usr' and token == '/local':
        value = -0.95
    elif previous == '/local' and token == '/bin':
        value = -0.54
    elif previous == '.util' and w in {'list', 'date', 'datetime', 'regex'}:
        value = -0.8
    elif previous == '.commons' and token.startswith('.'):
        value = -2.0
    elif p in {'open', 'pop', 'popular'}:
        value = response(w, OTHER_PHRASES['openness'])
    elif token in {'</tool_call>', '</tool_response>', '<|im_end|>'}:
        value = 0.08
    elif first:
        value = {'package': 0.36, 'private': 1.6}.get(w, 0.0)
    elif previous.strip() == '사용' and token == '자':
        value = -1.5
    return (doc, token), float(value)

"""A local person-to-action/property transition detector.

Positive responses mark actions or properties after human references. The main
case is infinitival 'to', amplified by a recent enabling/requesting verb. Human
nouns respond more strongly than object pronouns; collectives/animals are weaker.
Another person label instead gives a negative response, as does a person label
at the beginning of a document.
Chinese/Japanese human references use analogous particles and property words.
The coefficients are coarse averages, not a token-ID lookup.
"""
READS = ()

PEOPLE = set('''person man woman boy girl child kid baby adult individual human
student teacher pupil learner user customer client consumer reader viewer player
gamer member participant patient doctor nurse researcher scientist worker employee
employer staff officer soldier police citizen resident voter parent mother father
son daughter brother sister friend family couple wife husband partner visitor guest
author writer artist actor actress singer musician audience coach athlete leader
manager director executive legislator politician physicist shareholder holder
executor developer expert professional merchant victim speaker spouse assistant
secretary vendor recipient applicant passenger investor miner farmer fan teenager
mom dad intern programmer foreigner supporter respondent tutor contractor petitioner
dancer buyer moderator publisher pilot beginner stranger somebody someone anyone
everyone nobody population community group team business company firm organization
institution agent creature animal dog cat fish bird entity neuron public personnel'''.split())
PEOPLE |= {w[:-1] + 'ies' if w.endswith('y') and w[-2] not in 'aeiou' else
           w + ('es' if w.endswith(('s', 'ch', 'sh', 'x')) else 's')
           for w in PEOPLE}
PEOPLE |= {'people', 'men', 'women', 'children', 'wives', 'others'}
PEOPLE |= set('''人 人们 人們 人民 公众 公眾 人员 人員 大家 他人
用户 用戶 学生 學生 同学 同學 同学们 同學們 医生 醫生
教师 老師 家长 家長 消费者 消費者 观众 觀眾 听众 聽眾
居民 员工 員工 孩子 儿童 兒童 成员 成員 会员 會員
投资者 投資者 记者 記者 者 自分 みんな さん'''.split())

PRONOUNS = {'me', 'you', 'him', 'her', 'us', 'them'}
COLLECTIVES_ANIMALS = set('''population community communities group groups team teams
business businesses company companies firm firms organization organizations
institution institutions entity entities animal animals creature creatures dog dogs
cat cats fish bird birds neuron neurons'''.split())
MODIFIERS = set('''young elderly individual old younger older adult ordinary normal
human public other different general common average fellow local single female male
senior private pregnant graduate'''.split())
PROPERTIES = set('''health safety experience satisfaction happiness opinion learning
rights choices profile location engagement perception interest protection behavior
behaviors tastes spending feelings feeling body mind life heart value comfort
wellbeing welfare dignity privacy needs interests knowledge ability skills lifestyle
memory input access education respect lives emotions attitudes confidence'''.split())
ACTIONS = {'playing', 'underwent', 'did', 'work', 'live', 'participate'}
MENTAL_ACTIONS = {'feel', 'learn', 'understand', 'gain', 'think'}
COPULAS = {'is', 'are', 'was', 'were', 'be', 'being', 'have', 'has', 'had'}

# Weights for human nouns and object pronouns, respectively.
RELATIONS = {
    'about': (0.50, 0.13),
    'from': (0.35, 0.27), 'on': (0.40, 0.22),
    'into': (0.45, 0.20), 'through': (0.35, 0.28),
    'in': (0.15, 0.05), 'with': (0.14, 0.08),
    'for': (0.22, 0.07), 'as': (0.15, 0.08),
    'of': (-0.10, 0.0), 'who': (-0.09, 0.0),
}
CJK_RELATIONS = set('的 の 在 于 於 で を に 与 與 对 對'.split())
CJK_ACTIONS = set('''参与 參與 进行 進行 购买 購買 学习 學習 生活 工作 不断 不斷
喜爱 喜愛 使用 理解 了解 完成 感到 继续 繼續 看 做 参加 參加 健康
权益 權益 意见 意見 心 的学习 的生活 的心'''.split())


# Ordinary object-control verbs: ask/enable/require someone to act.
CAUSATIVES = set('''allow encourage enable ask invite force require permit request remind
instruct teach tell help expect urge advise want forbid cause assist persuade
let make order'''.split())
# Regular English inflections, plus common irregular forms.
for verb in tuple(CAUSATIVES):
    CAUSATIVES.update({verb + 's',
                       verb + ('d' if verb.endswith('e') else 'ed'),
                       (verb[:-1] if verb.endswith('e') else verb) + 'ing'})
CAUSATIVES |= {'taught', 'told', 'made', 'forbade', 'forbidding',
               'letting', 'permitted', 'permitting', 'teaches'}



def person_kind(word):
    if word in PRONOUNS:
        return 'pronoun'
    # Chinese agent, personnel, crowd and plural-person suffixes.
    if word.endswith(('者', '员', '員', '众', '眾', '们', '們')):
        if word not in {'或者', '再者', '动员', '動員'}:
            return 'cjk'
    if word in PEOPLE:
        if any('\u3040' <= c <= '\u9fff' for c in word):
            return 'cjk'
        return 'collective' if word in COLLECTIVES_ANIMALS else 'human'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    history = () if initial else carry[1]
    previous = history[-1] if history else ''
    kind = person_kind(previous)
    word = prefix.token_strings[-1].strip().lower()
    current_kind = person_kind(word)
    value = 0.0

    if kind in {'human', 'collective', 'pronoun'}:
        pronoun = kind == 'pronoun'
        if word == 'to':
            enabled = any(w in CAUSATIVES for w in history[:-1])
            if pronoun:
                value = 0.73 if enabled else 0.39
            else:
                value = 1.17 if enabled else 0.61
        elif word in RELATIONS:
            value = RELATIONS[word][int(pronoun)]
        elif current_kind:
            value = -0.08 if pronoun else -0.30
        elif word in PROPERTIES:
            value = 0.08 if pronoun else (0.75 if previous == 'public' else 0.55)
        elif word in MENTAL_ACTIONS:
            value = 0.12 if pronoun else 0.38
        elif word in ACTIONS:
            value = 0.0 if pronoun else 0.20
        elif word in COPULAS:
            value = -0.07 if pronoun else 0.0
        elif word in {'back', 'away', 'out', 'off', 'down', 'together'}:
            value = 0.15 if pronoun else 0.30
        elif word in {',', '\n', 'and', 'or'}:
            value = 0.0 if pronoun else -0.04
        if kind == 'collective':
            value *= 0.6
    elif kind == 'cjk':
        if current_kind:
            value = -0.45
        elif word in CJK_RELATIONS:
            value = 0.45
        elif word in CJK_ACTIONS:
            value = 0.95
        elif word.isalpha():
            value = 0.18

    if initial and current_kind:
        if current_kind == 'pronoun':
            value = -0.20
        elif current_kind == 'collective':
            value = -0.15
        elif current_kind == 'cjk':
            value = -0.75
        else:
            value = -0.70 if prefix.token_strings[-1].startswith(' ') else -0.50
    elif current_kind and previous in MODIFIERS:
        value = min(value, -0.12)
    return (doc, (history + (word,))[-6:]), value

