programs.sol:
"""A short-delimiter detector, dominated by the ASCII double dash.

Predict a strong positive response to --, less to ---, double underscores,
and familiar heading/comment/operator marks. Long separator rules are weaker;
unrecognized tokens get zero. Attached spaces and newlines change the response.
Recent double dashes attenuate later ones; document starts/newlines boost them.
"""
import math

READS = ()

# Recognizable punctuation forms, not word or token-ID lookups.
DELIMITERS = {
    '__': 1.44, '.__': 1.62, '/__': 1.54,
    '__/': 0.83, '__.': 0.50, '__(': 0.26,
    '-->': 1.60, '<!--': 1.85,
    '==': 1.20, '===': 0.83,
    '//': 0.90, '///': 0.24, '//#': 0.80, '"//': 2.07,
    '/*': 0.94, '#!/': 0.63, '::': 0.66,
    '!=': 0.44, '!==': 0.67, '++': 1.04, '+=': 0.38,
    '->': -0.02, '<-': 0.32, '..': 0.25, '...': -0.13,
    '``': 0.18, '(-': 0.25, '[-': 0.49, '{-': 0.50,
    ',-': 0.25, '=-': 0.25,
}
SPACE_ADJUSTMENT = {
    '__': 0.20, '===': 0.28, '//': -0.13, '///': 0.12,
    '//#': -0.24, '!=': 0.21, '++': 0.47, '->': 0.19,
    '::': 0.36, '/*': -0.10,
}


def delimiter_value(token):
    text = token.strip()
    spaced = token.startswith(' ')
    newline = token.endswith(('\n', '\r'))
    if token == '\r':
        return 0.92
    if not text:
        return 0.0
    if set(text) == {'-'}:
        n = len(text)
        if n == 1:
            return -0.03
        if newline:
            return (2.44 if spaced else 1.65) if n == 2 else 0.65
        if n == 2:
            return 5.08 + 0.48 * spaced
        if n == 3:
            return 2.66 + 0.30 * spaced
        return 2.3 if n == 4 else (1.0 if n <= 16 else 0.6)
    if text.startswith(('—', '–')):
        return 0.42 if newline else 0.95
    if (text.endswith('--') and text[:-2]
            and all(c in "('\")[." for c in text[:-2])):
        if text == '.--':
            return 4.1
        return 6.0 if any(c in "'\"" for c in text[:-2]) else 5.1
    # Arabic tatweel is a horizontal elongation stroke.
    if text == 'ـ':
        return 2.3
    if text in ('~', '~~', '～', '〜'):
        return 0.29
    if set(text) == {'#'}:
        n = len(text)
        if n == 1:
            return 0.10 + 0.10 * spaced
        return (0.54 + 0.14 * spaced) if n == 2 else (0.64 if n == 4 else 0.46)
    value = DELIMITERS.get(text, 0.0)
    if spaced:
        value += SPACE_ADJUSTMENT.get(text, 0.0)
    if newline:
        if text == '__':
            return 0.53
        if text == '///':
            return 0.08
        return 0.7 * value
    return value


def step(carry, prefix, upstream):
    # Recent repetition decays each token and resets at document boundaries.
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, recent, previous = 0, 0.0, ''
    else:
        _, position, recent, previous = carry
    token = prefix.token_strings[-1]
    value = delimiter_value(token)
    if token.strip() == '--' and not token.endswith(('\n', '\r')):
        gain = (1.05 + 0.17 * math.exp(-position / 32)
                - 0.0085 * math.log1p(position)
                - 0.09 * math.log1p(recent)
                + 0.08 * ('\n' in previous))
        value *= max(0.4, gain)
        recent += 1.0
    return (doc, position + 1, recent * 0.98, token), float(value)

