"""Separator-token detector for layers.0.mlp.down_proj:3035.

The component fires on visual separator and decoration tokens. Its strongest
response is to a bare double dash ("--" or " --"), the usual command-line flag
or comment-rule marker. It responds more weakly to other dash runs, underscore
runs ("__"), em and en dashes, equals signs, comment markers ("//", "/*", "##")
and "::", and weakly on "///" and " #". It stays silent on ordinary words, on a
lone "_" and on a lone "#". Each token gets the typical strength of its kind; the program does
not model the surrounding text.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

DOUBLE_DASH = 5.2   # "--" and " --" as their own token
DASH_MIX = 2.6      # other tokens built around "--": "---", ".--", '("--'
DASH_ARROW = 1.5    # " -->"
DASH_LINE = 1.0     # "--\n", "---\n": a dash run that ends a line
LONG_RULE = 1.2     # long rules such as "----------------"
UNDERSCORE = 1.4    # "__" runs (a lone "_" does not fire)
EM_DASH = 1.0       # "—" and "–", with or without a leading space
EQUALS = 1.1        # "==" and " =="
TRIPLE_EQUALS = 0.85
NOT_EQUALS = 0.65   # "!=", " !="
PLUS = 1.0          # "++"
SLASH = 0.8         # "//", " //", "/*"
COLON = 0.65        # "::"
HASH = 0.5          # "##", "###", "####"
CARRIAGE = 0.8      # "\r"


def strength(token: str) -> float:
    core = token.strip(" ")
    if core == "--":
        return DOUBLE_DASH
    if "--" in token:
        if "->" in token:
            return DASH_ARROW
        if token.endswith("\n"):
            return DASH_LINE
        if set(token.strip()) == {"-"} and len(token.strip()) > 4:
            return LONG_RULE
        return DASH_MIX
    if "__" in token:
        return UNDERSCORE
    if core in ("—", "–", "——"):
        return EM_DASH
    if core == "==":
        return EQUALS
    if core == "===":
        return TRIPLE_EQUALS
    if core in ("!=", "!=="):
        return NOT_EQUALS
    if core == "++":
        return PLUS
    if core == " ++":
        return 1.5
    if core == "+=":
        return 0.4
    if core in ("//", '"//', "/*"):
        return SLASH
    if core in ("///", " ///", " #"):
        return 0.3
    if core == "::":
        return COLON
    if core in ("##", "###", "####"):
        return HASH
    if token == "\r":
        return CARRIAGE
    return 0.0


def step(carry, prefix, upstream: Mapping):
    return None, strength(prefix.token_strings[-1])

