DOUBLE_WEIGHT = {
    "ll": 1.0, "kk": 0.8, "bb": 0.7, "dd": 0.55, "nn": 0.5, "tt": 0.45,
    "rr": 0.4, "ff": 0.4, "cc": 0.4, "zz": 0.4, "mm": 0.35, "pp": 0.35,
    "ww": 0.3, "ss": 0.25, "gg": 0.2,
