def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.0
    for pair, weight in DOUBLE_WEIGHT.items():
        if pair in word:
            value = max(value, weight)
    if word.endswith("ll"):
        if len(word) <= 3:
            value = 2.2  # all, ill, ell, oll
        elif len(word) == 4:
            value = 1.3  # hall, fall, wall, will, well
        else:
            value = 0.9  # small, still, football
    if "__" in word or "<<" in word:
        value = max(value, 0.6)
    return None, value

