"""A local spelling detector for continuations after L.

A token ending in l/L (and related letters in other scripts) primes the next
word fragment. Vowel-initial fragments are positive; doubled L and elision
apostrophes are negative. Familiar suffixes and syllable shapes adjust the
strength. Word boundaries are nearly silent. Only the preceding token is used;
these rules approximate, rather than reproduce, the component's computation.
"""
import unicodedata

READS = ()
L_LETTERS = frozenset('lлłλلลļľ')
VOWELS = {'a': .58, 'а': .58, 'e': .43, 'е': .43,
          'i': .87, 'и': .87, 'і': .87, 'o': .66, 'о': .66,
          'u': .64, 'у': .64, 'ю': .64, 'y': .53, 'ы': .53, 'я': .53}
GRAMMATICAL_SUFFIXES = frozenset((
    'ing', 'ings', 'ed', 'er', 'ers', 'est', 'ity', 'ities', 'ness',
    'ment', 'mente', 'ation', 'ations', 'ating', 'ated', 'able', 'ary', 'al',
))


def l_strength(token):
    s = token.lower()
    if not s:
        return 0.0
    c = s[-1]
    if c in L_LETTERS:
        if s.endswith('ll'):
            return .60
        return 1.16 if c == 'л' else 1.12 if c == 'ل' else 1.0
    if s.endswith('ль'):
        return .22
    # Hangul syllables whose final consonant is rieul (L/R).
    if '\uac00' <= c <= '\ud7a3' and (ord(c) - 0xac00) % 28 == 8:
        return .19
    if len(s) > 1 and s[-2] in L_LETTERS:
        return .10
    return .04 if any(c in L_LETTERS for c in s[-4:]) else 0.0


def continuation(token):
    if not token or token[0].isspace():
        return 0.0
    s = token.lower()
    if s[0] in "'’":
        if len(s) == 1:
            return -1.30 if s == "'" else -1.70
        if s in ("'s", '’s') or not s[1].isalpha():
            return -.06
        return -1.5 if s[1:] == 'é' else -.70
    if not s[0].isalpha():
        return 0.0
    if s[0] in L_LETTERS:
        return -.70 if len(s) == 2 and s[1] != 'y' else -.30
    if s.startswith(('ization', 'isation', 'izing', 'ising', 'ized',
                     'ised', 'ize', 'ise', 'ifying', 'ifies')):
        return .14
    if s in GRAMMATICAL_SUFFIXES:
        return .07
    if s in ('ist', 'ists', 'ista', 'istas', 'ист', 'исты'):
        return 1.48
    if s in ('ism', 'isms', 'изм'):
        return .70
    if s in ('ine', 'ines'):
        return 1.61
    if s in ('ic', 'ics', 'ical'):
        return .73
    if s[0] in 'äöü':
        return .96
    c = unicodedata.normalize('NFD', s)[0]
    if c not in VOWELS:
        return -.10 if s[0] in 'hfp' else .13
    if len(s) == 3 and s.endswith(('ng', 'нг')):
        return 1.9 if c in 'aаoо' else 1.0
    if s.endswith('ing'):
        return .10
    if c in 'aа' and s[1:2] == 'r':
        return 0.0
    if s.endswith(('l', 'л')):
        return -.30
    value = VOWELS[c] - .107 * min(max(len(s) - 2, 0), 6)
    following = s[1:2]
    if following in ('r', 'l', 'р', 'л'):
        value -= .357
    if following in ('k', 'g', 'к', 'г'):
        value += .333
    if following and following in 'aeiouy':
        value -= .136
    if following and following in 'bpfv':
        value += .209
    if len(s) == 1:
