SIZE_DEGREE = {'大', '小', '多', '少', '很', '最'}
TEXT_UNITS = {'字母', '词', '詞', '句子'}
NUMBERS = {'one', 'two', 'three', 'four', 'five', 'six', 'seven',
           'eight', 'nine', 'ten'}
QUANTIFIERS = NUMBERS | {'single', 'another', 'each', 'several', 'multiple'}
AUXILIARIES = {'is', 'are', 'was', 'were', 'can', 'may', 'might', 'could',
          'will', 'would', 'should', 'does'}
SIZE_WORDS = {'full', 'big', 'small', 'large', 'little', 'major',
              'long', 'short', 'very', 'extra', 'main'}


def activation(token, previous):
    value = 0.1 if token in TIME_UNITS else 0.0
    if token == '字':
        value = 0.13
    elif token == '多':
        value = 0.12

    if previous.endswith(('个', '個')):
        chinese = any('\u3400' <= c <= '\u9fff' for c in token)
        value = (0.48 if len(token) == 1 else 0.3) if chinese else 0.18
        if token in TIME_UNITS:
            value = 1.45
        elif token == '字':
            value = 1.55
        elif token in TEXT_UNITS:
            value = 0.7
        elif token in SIZE_DEGREE:
            value = 0.95
        if previous.endswith(('这个', '那个', '這個', '那個')):
            value *= 0.55
        elif previous.endswith(('整个', '整個')):
            value *= 0.3
    elif previous.strip().endswith('개') and any('가' <= c <= '힣' for c in token):
        value = 1.1 if token == '월' else 0.32
    else:
        word, before = token.strip().lower(), previous.strip().lower()
        if before in QUANTIFIERS and word.isalpha():
            value = 0.03
            if before == 'another' and word == 'try':
                value = 0.8
            elif word in AUXILIARIES:
                value = 0.12
            elif word in SIZE_WORDS:
                value = 0.17
            elif word in QUANTIFIERS:
                value = -0.04
            elif word == 'of':
                value = -0.04
                if before == 'several':
                    value = 0.25
                elif before == 'each':
                    value = 0.1
    return float(value)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), activation(token, previous)

