programs.sol:
"""A spelling-based detector of short capital-letter islands.

Two capitals give the strongest negative response, three a weaker one.
Vowels strengthen these short fragments; long capital runs and capitalized
surroundings weaken their response. Single capitals matter as continuations. Plural endings, repeated-I
Roman numerals, short mixed-case patterns, and pH get simple adjustments.
Other text stays at zero. History resets at each document boundary.
"""
from collections import deque

READS = ()


def capital_fraction(counts):
    return sum(a for a, b in counts) / max(1, sum(b for a, b in counts))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        trail, recent = 0, deque(maxlen=32)
    else:
        _, trail, recent = carry
    text = prefix.token_strings[-1]
    word = text.strip()
    plural = word.endswith('s') and word[:-1].isupper()
    core = word[:-1] if plural else word
    spaced = text[:1].isspace()
    before = 0 if spaced else trail
    value = 0.0
    if core.isascii() and core.isalpha() and core.isupper():
        history = list(recent)
        context = (2 * capital_fraction(history[-8:])
                   + capital_fraction(history)) / 3
        n = len(core)
        vowels = sum(c in 'AEIOU' for c in core)
        if n in (2, 3):
            if n == 2:
                value = -0.61 - 0.15 * min(vowels, 2) + 0.45 * context
            else:
                value = -0.32 - 0.08 * (vowels >= 2) + 0.28 * context
            value -= 0.05 * spaced
            if before == 1:
                value -= 0.10
            elif before >= 2:
                value += (0.50 if n == 2 else 0.28) * (0.7 if before == 2 else 1)
            if spaced and trail >= 2:
                value += 0.52 if n == 2 else 0.25
            if core == 'I' * n:
                value += 0.62 if n == 2 else 0.23
        elif n == 1 and before:
            value = -0.35 + 0.05 * context
            if before >= 3:
                value += 0.12 if before < 5 else 0.23
            if plural:
                value -= 0.20
        elif n == 4:
            value = -0.28 + 0.20 * (vowels > 0) + 0.07 * (vowels > 1)
            value += 0.11 * context
        elif n >= 5:
            value = 0.05
    elif word == 'pH':
        value = -0.60
    elif (word.isascii() and word.isalpha() and len(word) == 3
          and sum(c.isupper() for c in word) >= 2):
        value = -0.40
    capitals = sum('A' <= c <= 'Z' for c in text)
    letters = sum(c.isascii() and c.isalpha() for c in text)
    for char in text:
        trail = trail + 1 if 'A' <= char <= 'Z' else 0
    recent.append((capitals, letters))
    return (doc, trail, recent), float(value)

