"""A selective negative detector for 'ng' spellings, especially the ong rime.

It responds most to ong, song, long, along, strong, and young, and less to
among, during, their relatives, and short ang/eng/ung syllables. Case and a
leading space change some amplitudes. This is a lexical spelling feature,
not a general meaning-of-length detector or a detector of every -ing word.
Only the current token is used; other tokens get a near-zero prediction.
"""
import re

READS = ()
CONSONANTS = 'bcdfghjklmnpqrstvwxyz'


def response(raw):
    surface = raw.strip().strip('._-()[]{}<>/')
    word = surface.lower()
    capital = surface[:1].isupper()
    spaced = raw[:1].isspace()

    # The core words have much larger responses than their longer relatives.
    if word in ('ong', 'ongs'):
        return -5.6
    if word == 'song':
        return -5.2 if capital else -4.7
    if word == 'long':
        if capital:
            return -3.7 if spaced else -3.3
        return -3.0 if spaced else -3.8
    if word == 'along':
        return -4.2 if capital else (-3.3 if spaced else -3.8)
    if word == 'strong':
        return -4.0 if capital else (-3.2 if spaced else -2.7)
    if word == 'young':
        return -3.7 if capital else -2.8
    if word in ('among', 'during'):
        return -2.0 if word == 'among' else -1.7
    if word == 'songs':
        return -3.0
    if re.fullmatch('[' + CONSONANTS + ']{1,3}ong', word):
        return -0.3 if word == 'wrong' else -3.5

    # Inflected and extended spellings are weaker than the short roots.
    if word.startswith(('long', 'strong', 'along', 'among', 'elong',
                        'prolong', 'belong', 'strengthen')):
        return -1.2
    if word in ('large', 'throughout', 'soon', 'tongue', 'ongoing'):
        return -0.8
    if word in ('larger', 'largest', 'younger', 'youngest'):
        return -0.4

    # Small nasal-ending syllables, but not the common English -ing suffix.
    if word == 'ng':
        return -1.7 if capital else (-0.9 if spaced else -1.3)
    if word in ('eng', 'äng', 'läng', 'änger'):
