TRAILING_LETTERS = re.compile(r"[^\W\d_]+$", re.UNICODE)
INITIAL_STRENGTH = (0.35, 0.30, 0.19, 0.08)
LATER_STRENGTH = (0.11, 0.05, 0.04, -0.02)


