    boundary = bool(token and (
        not token[0].isalpha() or not previous
        or not previous[-1].isalpha()
        or previous.endswith(("\\n", "\\t", "\\r"))
    ))
    state = (doc, token, boundary)
    if not token or not token[0].isalpha():
        return state, 0.0
    match = TRAILING_LETTERS.search(previous)
    if match is None:
        return state, -0.02
