            factor = 1.0 if length <= 2 else 0.35
        elif length == 1:
            factor = 1.3
        elif token[0].lower() in "aeiou":
            factor = 1.5 if length == 2 else 1.15 if length == 3 else 1.0
        else:
            factor = 1.15 if length == 2 else 0.7
        value *= factor
