Well Now Also First Second Finally However Therefore Thus Here There Indeed
Instead Hi Hello Hey Oh Hmm Sorry Thanks Thank Yes Not Please Wow Oops
'''.split())
CODE_AND_INSTRUCTION_WORDS = set('''
