    'quote': (0.57, 0.33),
    'open': (0.51, 0.83),
    'close': (0.36, 0.89),
    'semicolon': (0.38, 0.61),
    'comma': (0.17, 0.19),
    'sentence': (0.02, 0.07),
    'whitespace': (0.28, 0.92),
    'newline': (0.34, 0.92),
    'upperword': (0.24, 0.39),
    'word': (-0.03, -0.04),
    'start': (0.08, -0.06),
    'symbol': (0.33, 0.70),
