        elif kind == 'marker' and spaced:
            value = 0.49
        elif kind == 'quote':
            value = 0.08
    elif word and word[0].islower():
        if kind.startswith('colon'):
            value = -0.04 if spaced else -0.10
        elif kind == 'marker' and not spaced:
            value = -0.07
        elif kind == 'comment':
            value = 0.06 if spaced else -0.04
    elif not word and kind.startswith('colon'):
