SCRIPT_LENGTHS = {
    'CYRILLIC': (1.05, 0.54, 0.19, 0.0),
    'ARABIC': (0.96, 0.37, 0.35, 0.1),
    'GREEK': (0.62, 0.1, 0.1, 0.0),
    'KATAKANA': (0.97, 0.34, 0.04, 0.04),
    'HIRAGANA': (0.29, 0.07, 0.07, 0.07),
    'HANGUL': (0.29, 0.07, 0.07, 0.07),
    'THAI': (0.85, 0.4, 0.4, 0.05),
