READS = ()

# Related law, jurisdiction, and public-administration terms.
PUBLIC_ADMIN = {
    "government", "governmental", "statutory", "nationwide",
    "commonwealth", "immigration", "federal", "federally",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if "federal" in word:
        return None, -4.1
    if "government" in word:
        return None, -0.9
    if word in PUBLIC_ADMIN:
        return None, -0.58
    return None, 0.0

programs.sol:
"""A lexical detector for absent/unspecified quantities and uncertain answers.

`none`/`None` is the dominant response; other indefinite words and null-like
values activate it moderately. Case and attached code punctuation change
its strength. `of` also activates immediately after `none`. This is a
word-level approximation, not a detector of every semantic negation.
Unlisted tokens predict zero. Only the immediately preceding token is
remembered, and this memory resets at document boundaries.
"""
READS = ()

# These are word classes, with strengths estimated on random training text.
# newaxis is NumPy's None alias; omitempty is Go's omit-empty marker.
ABSENT = {'null': 1.2, 'nil': 1.1, 'void': 0.75, 'nullptr': 2.2,
          'undefined': 1.05, 'unknown': 0.95, 'undisclosed': 0.8,
          'notimplemented': 1.0, 'omitempty': 1.0, 'newaxis': 5.3}
INDEFINITE = {'any': 1.46, 'some': 1.17, 'no': 0.88, 'non': 0.84,
              'never': 1.45, 'ever': 0.87, 'neither': 0.95,
              'few': 0.31, 'most': 0.30, 'anyone': 0.42,
              'anything': 0.27, 'anywhere': 0.39,
              'all': -0.10, 'everything': -0.63, 'everyone': -0.41,
              'nobody': 0.8, 'rarely': 0.85, 'seldom': 0.72,
              'little': -0.18, 'much': -0.12, 'each': -0.07}
UNCERTAIN = {'maybe': 0.81, 'perhaps': 0.65, 'probably': 0.33,
             'possibly': 0.40, 'sure': 1.3, 'certainly': 0.27,
             'unsure': 1.0, 'impossible': 0.28}
ANSWERS = {'yes': 0.87, 'done': 0.5, 'pure': 0.76,
           'option': 0.35, 'optional': 0.49, 'mixed': 0.52, 'todo': 0.94}

# Other languages: absence, indefinite quantity, enumeration, and purity.
OTHER_LANGUAGES = {
    'なし': 2.8, '無しさん': 2.1, 'なく': 0.94, 'ない': 0.44,
    '等': 1.02, 'など': 0.66, '任何': 1.22, '一些': 0.6,
    '非': 0.77, '无': 0.45, '無': 0.36, '少': 0.67, '全': 0.55,
    '纯': 1.05, '純': 0.8, 'nunca': 1.6, 'nada': 1.06,
    'jamais': 0.49, 'rien': 0.59, 'aucun': 0.96,
    'ninguna': 1.3, 'algunos': 0.7, 'algunas': 0.6,
}
STRENGTH = ABSENT | INDEFINITE | UNCERTAIN | ANSWERS | OTHER_LANGUAGES


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    spelling = token.strip()
    # Strip attached code punctuation, but preserve standalone operators.
    if any(c.isalpha() for c in spelling):
        spelling = spelling.lstrip('.([{<,=_-:/')
    word = spelling.lower()
    value = STRENGTH.get(word, 0.0)
    if word == 'none':
        if spelling != token.strip():
            value = 7.1
        elif spelling == 'NONE':
            value = 6.1
        elif token == 'None':
            value = 7.9
        else:
            value = 7.65
        # Python absence tests are weaker than returning/annotating None.
        if previous == 'not':
            value = 5.55
        elif previous == 'is':
            value = 6.9
        elif previous == '=':
            value = 7.25
        elif previous in ('return', '|', '->', ':'):
            value = 8.2
    elif word == 'of' and previous == 'none':
        value = 2.1
    elif word == 'some' and spelling == 'Some':
        value = 1.34 if token.startswith(' ') else 1.53
    elif word == 'no':
        if spelling == 'NO' or token == 'no':
            value = 0.57
        elif spelling == 'No':
            value = 0.80
    elif word == 'most':
        value = 0.08 if previous == 'the' else 0.52
        if previous == 'at':
            value = 0.17
    elif word == 'sure':
        if previous in ('make', 'makes', 'making'):
            value = 0.91
        elif previous in ('not', "'t", 'pretty'):
            value = 1.0
        elif spelling[0].isupper():
            value = 1.45
    elif word == 'null' and previous == 'not':
        value = 0.50 if spelling == 'NULL' else 0.80
    elif word == '有的':
        # Chinese 'some' versus the tail of ownership/existence compounds.
        value = 2.95 if previous in ('，', '。', '、') else 1.2
        if previous.endswith(('所', '所未', '拥')):
            value = 0.0
    elif word == 'yes' and token == 'yes':
        value = 0.5
    elif word == 'any':
        if spelling == 'Any':
            value = 1.55
        elif token == 'any':
            value = 1.1
    elif word in ('true', 'false'):
        if spelling in ('True', 'False'):
            value = 0.45 if token.startswith(' ') else 0.65
        elif spelling.isupper():
            value = 0.18
        else:
            value = 0.06
    return (doc, word), float(value)

programs.luna:
"""Recognize words for absence, uncertain status, and open quantity."""
READS = ()

NONE = {"none"}
ABSENCE = {"no", "non", "null", "nil", "void", "nothing", "neither"}
OPEN_QUANTITY = {"some", "any"}
SMALL_QUANTITY = {"most", "few", "several", "少"}
UNCERTAIN = {"maybe", "perhaps", "possibly", "probably", "unknown", "undisclosed"}
AFFIRMATION = {"yes", "true", "sure"}
EDGE_PUNCTUATION = " \t\r\n.,!?;:()[]{}\"'`"


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(EDGE_PUNCTUATION).lower()
    document = prefix.document_ids[-1]
    previous = None
    if carry is not None and carry[1] == document:
        previous = carry[0]

    value = 0.0
    if word in NONE:
        value = 8.0
    elif word in OPEN_QUANTITY:
        value = 1.35
    elif word in SMALL_QUANTITY:
        value = 0.5
    elif word in ABSENCE | UNCERTAIN | AFFIRMATION:
        value = 0.85
    elif word in {"全", "jamais"}:
        value = 0.65
    elif word == "of" and previous == "none":
        value = 1.5
    return (word, document), value

"""Estimate the sparse negative response to contrastive words such as “but”.

English “however” has the largest response. The rule also catches a word split
across tokens (notably French “cependant”); unrelated positions are zero.
"""

READS = ()


def response(word):
    lower = word.casefold()
    if lower == "however":
        return -8.0 if word[:1].isupper() else -6.5
    if lower == "but":
        return -1.4 if word[:1].isupper() else -0.85
    return {
        "mais": -0.4,
        "но": -0.7,
        "却": -0.6,
        "卻": -0.5,
        "但": -0.6,
        "だけど": -0.4,
        "cependant": -0.28,
    }.get(lower, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prior_doc, tail = carry if carry is not None else (doc, "")
    if doc != prior_doc:
        tail = ""

    piece = prefix.token_strings[-1]
    if piece[:1].isspace():
        tail = ""
    for char in piece:
        if char.isalpha():
            tail += char
        else:
            tail = ""

    # Exact token text also handles scripts with no spaces between words.
    exact = piece.strip()
    word = exact if response(exact) else tail
    value = response(word)
    return (doc, tail), float(value)

programs.sol:
"""A spelling-continuation approximation.

Remember the preceding token within each document.  A short consonant onset
such as 'tr', 'ch' or 'pl' gates a response to the next token's spelling:
consonant and numeral starts tend positive, short vowel starts negative.
Vowel/coda groups, boundary spelling and French qu' elision refine this rule.
At a document start, an onset token gets a moderate positive estimate.
The many smaller, token-specific activations are not modeled.
"""
READS = ()
ONSETS = frozenset('''br cr dr fr gr pr tr bl cl fl gl pl sl
sc sk sm sn sp st sw ch ph sh th wh qu zh scr spr str thr sch'''.split())
VOWELS = 'aeiouy'
CODAS = {'nasal':'mn', 'liquid':'rl', 'sibilant':'sz', 'stop':'pbtdkg'}
VOWEL_START = {'a':-0.06, 'e':-0.01, 'i':-0.01, 'o':0.02, 'u':-0.08}
SHORT_VOWEL = {'a':-0.10, 'e':-0.09, 'i':-0.03, 'o':-0.04, 'u':-0.05}
CODA_ADJUSTMENT = {
    'a': {'liquid':-0.06, 'sibilant':-0.15, 'stop':-0.04},
    'e': {'nasal':0.09, 'liquid':0.02, 'sibilant':0.07, 'stop':0.09},
    'i': {'sibilant':0.09, 'stop':0.08},
    'o': {'nasal':-0.02, 'liquid':-0.02, 'sibilant':-0.08, 'stop':-0.07},
    'u': {'nasal':0.02, 'sibilant':-0.02, 'stop':0.08},
}
FRENCH_SUBJECTS = frozenset('il ils elle elles on'.split())


def onset(text):
    return text.strip().lstrip('._/-').lower()


def onset_strength(text):
    word = text.strip().lstrip('._/-')
    low = word.lower()
    return (1.0 + 1.56*(low=='qu') + 0.14*word.istitle()
            + 0.18*text[:1].isspace() + 0.64*(text[:1] in '._/-')
            - 0.29*(len(word)>=3) - 0.20*low.startswith('s')
            + 0.29*(low=='st'))


def continuation(text):
    first = text[:1].lower()
    word = ''.join(c for c in text.lower() if c.isalpha())
    value = 0.055*first.isspace() + 0.32*first.isdigit()
    punctuation = bool(first) and not first.isalnum() and not first.isspace()
    value += 0.086*punctuation - 0.05*(punctuation and len(text)>1)
    value += 0.084*(first in ["'", '’']) - 0.01*(first=='.')
    if word and word.isascii() and not any(c in VOWELS for c in word):
        value += 0.08
    if first and first.isascii() and first.isalpha() and first not in VOWELS:
        value += 0.23 + 0.065*(len(word)==1) - 0.25*(first in 'rl')
    if first in VOWEL_START:
        value += VOWEL_START[first]
        if len(word)<=2:
            value += SHORT_VOWEL[first]
        second = word[1:2]
        for group, letters in CODAS.items():
            if second and second in letters:
                value += CODA_ADJUSTMENT[first].get(group, 0.0)
    return value


def french_elision(text):
    remainder = text[1:].lower()
    if not remainder:
        return 0.80
    if remainder == 'est':  # copula
        return 0.90
    if remainder == 'en':
        return 0.54
    if remainder == 'à':
        return 0.35
    if remainder in ('un', 'une'):
        return 0.22
    if remainder in FRENCH_SUBJECTS:
        return 0.14 if text == "'il" else 0.02
    return 0.20


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    value = 0.001
    if carry is None or carry[0] != document:
        if onset(text) in ONSETS:
            value = 0.36
    elif onset(carry[1]) in ONSETS:
        if onset(carry[1]) == 'qu' and text.startswith(("'", '’')):
            value = french_elision(text)
        else:
            value += onset_strength(carry[1])*continuation(text)
    return (document, text), float(value)

programs.haiku:
"""Words of drawing, attracting, provoking or triggering: a pull or push that sets something off.

The Chinese character 引 ("to draw, pull, lead on, cite, cause") is the strongest trigger,
bare and in compounds such as 引起, 引发, 吸引, 引用, 引导. Other pull, provoke and borrow
words in Chinese (惹, 弓, 牵, 借, 援, 诱惑) get smaller values. English words for attracting,
triggering, provoking, inducing, invoking, borrowing and gravity get smaller ones still. Every
other token predicts 0.
"""
READS = ()

CHINESE = {"引": 6.0, "引き": 5.0, "引起": 3.0, "引发": 2.5, "吸引": 2.8, "引用": 2.7,
           "引进": 2.2, "引导": 2.2, "指引": 1.4, "惹": 2.4, "弓": 3.0, "牵": 1.5,
           "借": 0.9, "借用": 1.0, "援": 1.0, "诱惑": 0.6, "诱人": 0.5, "留": 0.6}

# English stems and their values
ENGLISH = {"attract": 1.1, "trigger": 0.85, "provok": 0.6, "ignit": 0.6, "influenti": 0.5,
           "gravit": 0.5, "influenc": 0.35, "intrigu": 0.4, "invok": 0.4, "induc": 0.35,
           "borrow": 0.35}

def value(tok):
    if tok in CHINESE:
        return CHINESE[tok]
    if "引" in tok:
        return 2.5
    low = tok.lower()
    for stem, v in ENGLISH.items():
        if low.startswith(stem):
            return v
    return 0.0

def step(carry, prefix, upstream):
    return None, float(value(prefix.token_strings[-1].strip()))

programs.sol:
"""Mostly a spelling detector for 'us', not a taxonomy or meaning detector.

Bare '-us' pieces (often Latin names/endings) respond more strongly than
space-prefixed words; '-ius' is especially strong and adjectival '-ous' weak.
Common whole words have lower calibrated responses. Smaller rules cover
related endings, Cyrillic/Japanese/Korean spellings, and literal markup,
hesitation and JavaScript markers. Other tokens predict zero. Constants
approximate training activations; contextual and negative activity is omitted.
"""
READS = ()

COMMON_US_WORDS = {
    'plus', 'minus', 'status', 'virus', 'calculus', 'stimulus',
    'modulus', 'radius', 'campus', 'bonus', 'chorus', 'surplus',
}
LATIN_NOUNS = {'genus', 'corpus', 'fetus', 'locus', 'nexus'}


def response(token):
    # These are literal protocol markers, not general angle-bracket text.
    if token == '<tool_call>':
        return 0.96
    if token == '<tool_response>':
        return 0.24
    if token == '</think>':
        return 0.34
    if token in ('ス', 'す', '스'):
        return 0.75

    letters = token.lstrip(' \t\n._-/([\'"')
    word = letters.lower()
    boundary = letters != token
    if word.endswith('ус'):
        return 3.4 if word == 'ус' and not boundary else 1.5
    if word.endswith('us') and word.isascii() and word.isalpha():
        if word.endswith('ous'):
            if word == 'nous':
                return 0.8
            if word == 'ous':
                return 1.45
            if word == 'rous' and not boundary:
                return 2.3
            return 0.1 if boundary or len(word) >= 7 else 0.6
        if word == 'us':
            if letters == 'Us':
                return 1.5 if boundary else 1.1
            return (2.3 if letters == 'US' else 1.62) if boundary else 3.55
        if word == 'bus':
            return 3.1 if boundary else (6.0 if letters.islower() else 4.2)
        if word == 'thus':
            if letters.islower():
                return 1.58 if boundary else 1.95
            return 1.15
        if word in ('versus', 'apparatus', 'menus', 'hindus', 'seus'):
            return 0.2
        if word in COMMON_US_WORDS:
            return 1.05
        if word == 'focus':
            return 1.75
        if word == 'sus' and boundary and letters.islower():
            return 1.05
        if word in ('aus', 'haus'):
            if not boundary:
                return 2.85
            return 2.3 if word == 'aus' else 1.3
        if word in LATIN_NOUNS:
            return 2.75
        if not boundary:
            return 4.1 if word.endswith('ius') else 3.4
        return 2.2 if len(word) < 8 else 1.5

    if word == 'js':
        return 0.7
    if word == 'hmm':
        return 0.54
    if word == 'uses' and not boundary:
        return 1.5
    if word == 'uss':
        return 1.0
    if not boundary and word in ('usb', 'usc'):
        return 1.6
    if word.startswith('focus'):
        return 0.9
    if word in ('ium', 'orum', 'ensis'):
        return 0.8
    if len(word) >= 5 and word.isascii() and word.isalpha():
        if word.endswith('is'):
            return 0.3
        if word.endswith('as'):
            return 0.2
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))
